/*
 * b02-saas-payroll.js — "Payday at Risk" (branching, SaaS provider).
 *
 * The payroll provider is breached on salary day and stops all payroll runs.
 * Spine: first move → what data is in scope → pay or wait → staff questions →
 * payday phishing → the 72 hours (controller vs processor) → a second wave →
 * the next payroll run → what changes. Break-away at the notification page:
 * blaming the provider in public. Endings by flags: notified + staff told +
 * paid (contained) … unpaid and late (severe).
 */
(function () {
  "use strict";

  const BK = window.BK;
  const { L, q, inj, act, kpi, pg, ask, opt, pb, end, vr, rt } = BK.scenarios.h;

  BK.scenarios.register({
    id: "b02-saas-payroll",
    version: 1,
    format: "branching",
    category: "saas-provider",
    archetype: "third-party-origin",
    emblem: "payroll",
    title: L(["Payday at Risk", "Lönedag i fara"]),
    summary: L([
      "The day before payday, the payroll provider reports a breach and stops every payroll run. Thousands of people expect to be paid tomorrow, and their personal data may be gone.",
      "Dagen före lönedagen rapporterar lönetjänstleverantören ett intrång och stoppar alla lönekörningar. Tusentals personer räknar med lön i morgon, och deras personuppgifter kan vara borta."
    ]),
    learningObjectives: [
      { id: "lo1", text: L(["Keep a critical business process running when a SaaS provider fails", "Hålla en kritisk process igång när en SaaS-leverantör fallerar"]), teaser: L(["Keeping the everyday working", "Att hålla vardagen igång"]) },
      { id: "lo2", text: L(["Understand controller duties when the breach is at a processor", "Förstå den personuppgiftsansvariges skyldigheter när intrånget sker hos ett biträde"]), teaser: L(["Whose problem it is when it happens somewhere else", "Vems problem det är när det händer någon annanstans"]) },
      { id: "lo3", text: L(["Communicate with staff whose own data is affected", "Kommunicera med personal vars egna uppgifter berörs"]), teaser: L(["Talking to the people closest to you", "Att tala med dem som står er närmast"]) },
      { id: "lo4", text: L(["Spot fraud that exploits an incident", "Upptäcka bedrägerier som utnyttjar en incident"]), teaser: L(["Staying alert while everyone is busy", "Att vara vaksam när alla har fullt upp"]) }
    ],
    mitre: ["T1199", "T1078", "T1530", "T1566", "T1657"],
    frameworks: {
      nistCsf: ["GV.SC", "ID.RA", "RS.CO", "RS.MA", "RC.RP", "RC.CO"],
      iso27001: ["A.5.19", "A.5.20", "A.5.21", "A.5.22", "A.5.24", "A.5.26", "A.5.30"]
    },
    constraints: { startWindow: "business-hours", startTime: "07:10" },
    actor: { types: ["criminal"], motivation: L(["Financial: personal data for fraud and extortion of the provider", "Ekonomisk: personuppgifter för bedrägerier och utpressning av leverantören"]), capability: "medium" },
    variables: {
      payrollTotal: { min: 2000000, max: 90000000, scaleBy: "size", step: 100000, currency: true },
      fakeChanges: { min: 3, max: 40, scaleBy: "size" },
      payslipMonths: { min: 12, max: 36 }
    },
    roles: ["incidentCommander", "cfo", "hr", "ciso", "supplierManager", "legal", "dpo", "comms", "itOps", "ceo"],

    flags: {
      manualCancelled: L(["Manual payroll fallback cancelled", "Manuell reservlösning för lönen avbruten"]),
      manualPrep: L(["Manual payroll prepared early", "Manuell löneutbetalning förberedd tidigt"]),
      paidManual: L(["Salaries paid manually", "Löner utbetalda manuellt"]),
      payDelayed: L(["Salaries delayed", "Lönerna försenade"]),
      staffTold: L(["Staff told early", "Personalen informerad tidigt"]),
      changesFrozen: L(["Bank-detail changes frozen", "Ändringar av bankuppgifter frysta"]),
      notified: L(["You notified the DPA yourselves", "Ni anmälde själva till dataskyddsmyndigheten"]),
      waitedProvider: L(["Waited for the provider to notify", "Väntade på att leverantören skulle anmäla"]),
      terminated: L(["Contract terminated", "Avtalet uppsagt"])
    },

    start: "c1",
    pages: [
      pg("c1", ["The day before payday", "Dagen före lönedagen"], [
        "{{time.T+0|weekday|cap}}, {{time.T+0|clock}}. Tomorrow is payday. An email arrives from {{supplier.vendor}}, the cloud service that runs your payroll: “security incident under investigation, all payroll runs suspended until further notice”.\n\nFinance normally sends this month's payroll file to the bank this afternoon. The provider promises its next update at 09:00. Nobody in the building yet knows what “incident” means for your staff.",
        "{{time.T+0|weekday|cap}}, klockan {{time.T+0|clock}}. I morgon är det lönedag. Ett mejl kommer från {{supplier.vendor}}, molntjänsten som sköter era löner: ”säkerhetsincident under utredning, alla lönekörningar stoppade tills vidare”.\n\nEkonomi brukar skicka månadens lönefil till banken i eftermiddag. Leverantören lovar nästa uppdatering klockan nio. Ingen i huset vet ännu vad ”incident” betyder för er personal."
      ], {
        injects: [
          inj("b2-1", 0, "supplierNotice", "vendor", "high", "confirmed", [
            "We are investigating unauthorised access to parts of our platform. As a precaution all payroll runs are suspended. Next update 09:00.",
            "Vi utreder obehörig åtkomst till delar av vår plattform. Av försiktighetsskäl är alla lönekörningar stoppade. Nästa uppdatering 09.00."
          ], { headline: ["Service notice: payroll suspended", "Driftmeddelande: lönekörningar stoppade"], tests: ["lo1"] })
        ],
        discuss: [q("Who owns payroll when the system that runs it is gone?", "Vem äger lönen när systemet som kör den är borta?", ["cfo", "hr"])],
        facilitator: { notes: L(["Fast format: two minutes per choice. The real question is whether anyone starts on a fallback now.", "Snabbt format: två minuter per val. Den verkliga frågan är om någon börjar på en reservlösning redan nu."]) },
        choice: ask(["What do you do before the 09:00 update?", "Vad gör ni före uppdateringen klockan nio?"], ["Starts a payroll fallback in parallel instead of waiting for the provider.", "Startar en reservlösning för lönerna parallellt i stället för att vänta på leverantören."], [
          opt(["Convene finance, HR and security now", "Samla ekonomi, HR och säkerhet nu"], "c2", ["Gets the right people talking. Nobody yet owns the fallback.", "Får rätt personer att prata. Ingen äger ännu reservlösningen."], { pushback: [
            pb(["A meeting, not a plan", "Ett möte, ingen plan"], ["Forty minutes in, everyone agrees the situation is serious, but nobody has been told to build a payment file. Finance's usual slot with the bank is getting closer. Who leaves this room with the fallback as their job, by name?", "Efter fyrtio minuter är alla överens om att läget är allvarligt, men ingen har fått i uppdrag att ta fram en betalfil. Ekonomis vanliga tid mot banken närmar sig. Vem går ut ur rummet med reservlösningen som sitt ansvar, med namn?"]),
            pb(["Split on telling staff", "Oeniga om personalen"], ["{{person.hr.name}} argues that staff should hear something before rumours start; security says nothing goes out before the provider's update. The meeting is split down the middle. Do you decide it now, or does the meeting end without an answer?", "{{person.hr.name}} menar att personalen bör få höra något innan ryktena börjar; säkerhet vill att inget går ut före leverantörens uppdatering. Mötet är delat på mitten. Avgör ni det nu, eller slutar mötet utan svar?"]),
            pb(["Pulled off the month-end", "Bortdragna från bokslutet"], ["Convening finance pulls the payroll team off the month-end close the auditors expect this week. The finance manager asks whether this meeting is worth more than their deadline. Do you overrule the close, or send some of them back?", "Att samla ekonomi drar lönegruppen från månadsbokslutet som revisorerna väntar på den här veckan. Ekonomichefen frågar om mötet är värt mer än deras deadline. Kör ni över bokslutet, eller skickar ni tillbaka några av dem?"])
          ] }),
          opt(["Wait for the 09:00 update", "Vänta på uppdateringen klockan nio"], "c2", ["Two hours less to build a fallback if the update is bad.", "Två timmar mindre att bygga en reservlösning om beskedet är dåligt."], { pushback: [
            pb(["Finance sits idle", "Ekonomi sitter sysslolös"], ["The payroll team has nothing to do but wait, and the bank's cut-off for tomorrow's salaries is this afternoon. Every hour of waiting is an hour less to build a file by hand. If the update is bad, what is the latest moment you could still pay people?", "Lönegruppen har inget att göra annat än att vänta, och bankens brytpunkt för morgondagens löner är i eftermiddag. Varje timme ni väntar är en timme mindre att bygga en fil för hand. Om beskedet är dåligt, när är sista stund ni fortfarande kan betala ut?"]),
            pb(["Staff already know", "Personalen vet redan"], ["A screenshot of the provider's service notice is circulating in a staff group chat with the question “are we getting paid?”. Waiting for the update means saying nothing to people who already know something. What, if anything, do you tell them meanwhile?", "En skärmbild av leverantörens driftmeddelande cirkulerar i en gruppchatt bland personalen med frågan ”får vi lön?”. Att vänta på uppdateringen betyder att inte säga något till folk som redan vet något. Vad säger ni till dem under tiden, om något?"]),
            pb(["Other customers are moving", "Andra kunder agerar redan"], ["{{person.supplierManager.name}} hears from a contact at another customer of {{supplier.vendor}}: they have already started preparing salaries by hand. Your plan rests on the provider's update being worth waiting for. Why trust their timeline more than their other customers do?", "{{person.supplierManager.name}} hör från en kontakt hos en annan kund till {{supplier.vendor}}: de har redan börjat förbereda lönerna för hand. Er plan bygger på att leverantörens besked är värt att vänta på. Varför lita mer på deras tidsplan än deras andra kunder gör?"])
          ] }),
          opt(["Have finance prepare a manual payment file now", "Låt ekonomi förbereda en manuell betalfil nu"], "c2", ["Possibly wasted work. Possibly the only way people get paid.", "Kanske bortkastat arbete. Kanske det enda sättet att få ut lönerna."], { set: "manualPrep", pushback: [
            pb(["Which numbers?", "Vilka siffror?"], ["Finance can only build the file from last month's figures: this month's overtime, absences and new starters sit in the provider's system. Anyone paid from that file gets the wrong amount. Are you ready to pay people the wrong salary on purpose?", "Ekonomi kan bara bygga filen på förra månadens siffror: månadens övertid, frånvaro och nyanställda ligger i leverantörens system. Alla som får lön från den filen får fel belopp. Är ni beredda att medvetet betala ut fel lön?"]),
            pb(["Risk of paying twice", "Risk för dubbel lön"], ["The provider's account manager calls: salaries prepared outside their platform could mean double payments when service resumes, and they will not be responsible for that. Finance hesitates. Do you keep building the file, and who answers for a double payment?", "Leverantörens kundansvarige ringer: löner som förbereds utanför plattformen kan leda till dubbla utbetalningar när tjänsten är igång igen, och det tar de inget ansvar för. Ekonomi tvekar. Fortsätter ni bygga filen, och vem står för en dubbel utbetalning?"]),
            pb(["Who signs it?", "Vem skriver under?"], ["The bank wants a manual file of {{num.payrollTotal|currency}} approved by two authorised signatories. One is travelling; the other wants written instructions before signing anything unusual. Who gives that instruction, and on what basis, before anyone knows what happened?", "Banken vill att en manuell fil på {{num.payrollTotal|currency}} godkänns av två behöriga firmatecknare. En är på resa; den andra vill ha skriftliga instruktioner innan något ovanligt skrivs under. Vem ger den instruktionen, och på vilken grund, innan någon vet vad som hänt?"])
          ] })
        ])
      }),

      pg("c2", ["What do they have?", "Vad har de kommit åt?"], [
        "09:00. {{supplier.vendor}}'s update is short: the attacker reached “a limited set of customer data”, and they cannot yet say whose.\n\nYour payroll file is not limited. It holds names, personal identity numbers, home addresses, bank account numbers and salaries for {{org.headcount|number}} people. Until you know otherwise, any of it could be in someone else's hands.",
        "Klockan 09.00. {{supplier.vendor}}s uppdatering är kort: angriparen kom åt ”en begränsad mängd kunddata”, och de kan ännu inte säga vems.\n\nEr lönefil är inte begränsad. Den innehåller namn, personnummer, hemadresser, bankkontonummer och löner för {{org.headcount|number}} personer. Tills ni vet något annat kan vad som helst av det finnas hos någon annan."
      ], {
        discuss: [q("What exactly do you need the provider to confirm, in writing?", "Vad exakt behöver leverantören bekräfta skriftligt?", ["supplierManager", "dpo"])],
        choice: ask(["How do you establish what is exposed?", "Hur tar ni reda på vad som är exponerat?"], ["Asks for a written scope from the processor and plans for the worst until it arrives.", "Begär en skriftlig avgränsning från biträdet och planerar för det värsta tills den kommer."], [
          opt(["Demand a written statement of your data in scope", "Kräv ett skriftligt besked om vilka av era uppgifter som berörs"], "l1", ["The right request. Providers in a crisis answer slowly.", "Rätt begäran. Leverantörer i kris svarar långsamt."], { pushback: [
            pb(["A case number, no answer", "Ett ärendenummer, inget svar"], ["Your formal request gets an automatic reply with a case number and no expected response time. Every other customer is asking the same thing. While you wait for their written answer, what do you actually plan on?", "Er formella begäran får ett automatsvar med ärendenummer och ingen svarstid. Alla andra kunder frågar samma sak. Vad planerar ni faktiskt utifrån medan ni väntar på deras skriftliga svar?"]),
            pb(["Answered by lawyers", "Besvarat av jurister"], ["{{person.legal.name}} warns that a written demand will be answered by the provider's lawyers, carefully and narrowly. A narrow question gets a narrow answer. Do you word it broadly and risk a vague reply, or narrowly and risk missing what matters?", "{{person.legal.name}} varnar för att ett skriftligt krav kommer att besvaras av leverantörens jurister, försiktigt och snävt. En snäv fråga ger ett snävt svar. Formulerar ni den brett och riskerar ett luddigt svar, eller snävt och riskerar att missa det viktiga?"]),
            pb(["Your duties don't wait", "Era skyldigheter väntar inte"], ["{{person.dpo.name}} reminds you that your own duties as the employer holding this data do not pause until the provider writes back. A letter is good evidence, not a plan. What do you do today if no answer comes until tomorrow?", "{{person.dpo.name}} påminner om att era egna skyldigheter som arbetsgivare med de här uppgifterna inte pausas tills leverantören svarar. Ett brev är bra bevisning, inte en plan. Vad gör ni i dag om svaret dröjer till i morgon?"])
          ] }),
          opt(["Assume all employee data is exposed and plan for that", "Utgå från att alla personaluppgifter är exponerade och planera för det"], "l1", ["Safe planning basis. Might over-alarm staff if said too loudly.", "En säker grund för planeringen. Kan skrämma personalen i onödan om det sägs för högt."], { pushback: [
            pb(["“Everything is stolen”", "”Allt är stulet”"], ["Word gets out that management is “assuming everything is stolen”. Staff start calling their banks and asking HR to change account details. Do you stand by the worst case in public, or soften it and risk having to harden it again later?", "Det läcker ut att ledningen ”utgår från att allt är stulet”. Anställda börjar ringa sina banker och be HR byta kontouppgifter. Står ni för värsta fallet offentligt, eller tonar ni ned det och riskerar att behöva skärpa det igen senare?"]),
            pb(["The bill for worst case", "Notan för värsta fallet"], ["Planning for full exposure means support, bank letters and extra HR staff for everyone. {{person.cfo.name}} wants to see the cost before spending money on something nobody has confirmed. How much are you willing to spend on an assumption?", "Att planera för full exponering innebär stöd, brev till banker och extra HR-resurser för alla. {{person.cfo.name}} vill se kostnaden innan pengar läggs på något som ingen har bekräftat. Hur mycket är ni beredda att lägga på ett antagande?"]),
            pb(["“Very few customers”", "”Väldigt få kunder”"], ["The provider's account manager insists informally that “very few customers” are affected and that you are overreacting. If that is true, your plan will look like panic. Do you keep planning for the worst, or wait to be told whether you are in scope?", "Leverantörens kundansvarige försäkrar informellt att ”väldigt få kunder” berörs och att ni överreagerar. Stämmer det kommer er plan att se ut som panik. Fortsätter ni planera för det värsta, eller väntar ni på besked om ni berörs?"])
          ] }),
          opt(["Rely on the provider's public FAQ", "Lita på leverantörens offentliga frågor och svar"], "c3b", ["Easy, and written for the provider's lawyers, not for you.", "Enkelt, och skrivet för leverantörens jurister, inte för er."], { pushback: [
            pb(["Nothing about you", "Inget om er"], ["{{person.legal.name}} reads the FAQ twice: it never mentions your company, your data or any date. None of it would show that you assessed your own exposure. What will you point to when someone asks how you did that?", "{{person.legal.name}} läser frågor och svar två gånger: där nämns aldrig ert företag, era uppgifter eller något datum. Inget av det visar att ni bedömt er egen exponering. Vad pekar ni på när någon frågar hur ni gjorde det?"]),
            pb(["Staff read it too", "Personalen läser också"], ["Employees have found the same FAQ and quote it back to HR, asking why their employer knows no more than the public. Do you admit you have nothing more, or start asking the provider directly after all?", "Anställda har hittat samma frågor och svar och citerar dem för HR, och undrar varför arbetsgivaren inte vet mer än allmänheten. Erkänner ni att ni inte har mer, eller börjar ni ändå fråga leverantören direkt?"]),
            pb(["Quietly edited", "Tyst ändrat"], ["Late in the morning the FAQ is quietly edited: one reassuring sentence has disappeared, without explanation. You don't know what changed behind it. Do you keep relying on a document the provider rewrites without telling you?", "Sent på förmiddagen ändras frågor och svar i tysthet: en lugnande mening har försvunnit, utan förklaring. Ni vet inte vad som ändrats bakom den. Fortsätter ni lita på ett dokument som leverantören skriver om utan att säga till?"])
          ] })
        ])
      }),

      pg("l1", ["The contract", "Avtalet"], [
        "{{person.supplierManager.name}} digs out the data processing agreement signed four years ago. The provider must tell you about a breach within 24 hours, with details of the data involved.\n\nThere is also an audit right that nobody has ever used. Invoking it formally changes the tone of the relationship, on a day when you need the provider's help to pay people.",
        "{{person.supplierManager.name}} letar fram personuppgiftsbiträdesavtalet som skrevs under för fyra år sedan. Leverantören måste underrätta er om ett intrång inom 24 timmar, med uppgifter om vilken data som berörs.\n\nDär finns också en granskningsrätt som ingen någonsin har använt. Att åberopa den formellt ändrar tonen i relationen, en dag då ni behöver leverantörens hjälp för att kunna betala folk."
      ], {
        long: true,
        skipTo: "c3",
        choice: ask(["How do you use the contract?", "Hur använder ni avtalet?"], ["Invokes contractual rights early and in writing, without wrecking the working relationship.", "Åberopar avtalets rättigheter tidigt och skriftligt, utan att förstöra samarbetet."], [
          opt(["Invoke the breach and audit clauses formally", "Åberopa klausulerna om incidenter och granskning formellt"], "c3", ["Creates a paper trail and pressure. The provider becomes guarded.", "Skapar ett skriftligt spår och tryck. Leverantören blir mer försiktig."], { pushback: [
            pb(["The helpful contact goes quiet", "Den hjälpsamma kontakten tystnar"], ["Within an hour of your formal notice, the friendly account manager stops answering and refers you to a legal mailbox. You still need their help to get people paid. Was the paper trail worth losing the one person who was helping?", "Inom en timme efter er formella skrivelse slutar den vänliga kundansvarige svara och hänvisar till en juridisk brevlåda. Ni behöver fortfarande deras hjälp för att få ut lönerna. Var det skriftliga spåret värt att förlora den enda som hjälpte till?"]),
            pb(["Audit, but not now", "Granskning, men inte nu"], ["The provider replies that it will honour the audit right, but not during an active investigation, and proposes a date weeks away. On paper you won; in practice you have nothing. Do you push for access now and escalate, or accept the delay?", "Leverantören svarar att granskningsrätten gäller, men inte under en pågående utredning, och föreslår ett datum om flera veckor. På papperet vann ni; i praktiken har ni ingenting. Kräver ni åtkomst nu och trappar upp, eller accepterar ni dröjsmålet?"]),
            pb(["Who does the audit?", "Vem gör granskningen?"], ["{{person.ciso.name}} points out that nobody in-house has ever audited a payroll platform, and an external firm takes days to engage. Invoking the clause commits you to using it. Who actually carries out the audit, and what if you can't?", "{{person.ciso.name}} påpekar att ingen internt någonsin har granskat en löneplattform, och att det tar dagar att anlita en extern firma. Att åberopa klausulen förpliktar er att använda den. Vem gör granskningen i praktiken, och vad händer om ni inte kan?"])
          ] }),
          opt(["Keep it friendly for now", "Håll det vänligt tills vidare"], "c3", ["Preserves goodwill. Leaves you without leverage when you need it.", "Bevarar välviljan. Lämnar er utan påtryckningsmedel när ni behöver dem."], { pushback: [
            pb(["The 24 hours pass", "De 24 timmarna går"], ["The contract gives the provider 24 hours to tell you what data was involved. The deadline passes with friendly calls and nothing in writing, and there is no record you ever asked. Do you change tone now, after a deadline you chose not to enforce?", "Avtalet ger leverantören 24 timmar att berätta vilken data som berörs. Fristen går ut med vänliga samtal och inget skriftligt, och det finns inget som visar att ni frågade. Byter ni ton nu, efter en frist ni själva valde att inte hävda?"]),
            pb(["Your lawyer disagrees", "Er jurist håller inte med"], ["{{person.legal.name}} writes that not invoking the clause could later be read as accepting the provider's handling, and advises sending something formal today, however polite. Do you overrule your own lawyer to protect the relationship?", "{{person.legal.name}} skriver att det senare kan tolkas som att ni godtagit leverantörens hantering om klausulen inte åberopas, och råder er att skicka något formellt i dag, hur artigt som helst. Kör ni över er egen jurist för att skydda relationen?"]),
            pb(["Friendly to whom?", "Vänliga mot vem?"], ["Staff representatives hear that management is “keeping things friendly” with the company that may have lost their data. To them it sounds like you are protecting the supplier, not the employees. How do you explain that choice to the people whose data it is?", "Personalens företrädare hör att ledningen ”håller det vänligt” med företaget som kan ha tappat deras uppgifter. För dem låter det som att ni skyddar leverantören, inte de anställda. Hur förklarar ni valet för dem vars uppgifter det gäller?"])
          ] })
        ])
      }),

      pg("c3", ["Pay or wait", "Betala eller vänta"], [
        "Midday. The provider confirms it will not run any payroll today, and probably not tomorrow either. Salaries totalling {{num.payrollTotal|currency}} are due in people's accounts tomorrow morning.\n\nThe bank needs a payment file by 15:00 to make it. Some staff live from one salary to the next, and rent is due at the end of the week.",
        "Mitt på dagen. Leverantören bekräftar att den inte kör några löner i dag, och troligen inte i morgon heller. Löner på sammanlagt {{num.payrollTotal|currency}} ska finnas på folks konton i morgon bitti.\n\nBanken behöver en betalfil före klockan tre för att det ska hinna gå. En del anställda lever från lön till lön, och hyran ska betalas i slutet av veckan."
      ], {
        variants: [vr("manualPrep", [
          "Midday. The provider confirms it will not run any payroll today, and probably not tomorrow either. Salaries totalling {{num.payrollTotal|currency}} are due tomorrow morning.\n\nBecause finance started early, a manual payment file based on last month's salaries is ready to check. It will be wrong for anyone with overtime, sick leave or a new job this month, but it would get money into accounts.",
          "Mitt på dagen. Leverantören bekräftar att den inte kör några löner i dag, och troligen inte i morgon heller. Löner på sammanlagt {{num.payrollTotal|currency}} ska betalas ut i morgon bitti.\n\nEftersom ekonomi började tidigt finns en manuell betalfil baserad på förra månadens löner redo att granskas. Den blir fel för alla med övertid, sjukfrånvaro eller ny tjänst den här månaden, men den skulle få in pengar på kontona."
        ], ["Because a manual file was started early, paying on time is still possible.", "Eftersom en manuell fil påbörjades tidigt går det fortfarande att betala i tid."])],
        discuss: [q("What goes wrong if you pay everyone last month's amount?", "Vad blir fel om ni betalar alla förra månadens belopp?", ["cfo", "hr"])],
        choice: ask(["Do people get paid tomorrow?", "Får folk lön i morgon?"], ["Pays on time from a controlled fallback and corrects differences next month.", "Betalar i tid från en kontrollerad reservlösning och rättar skillnader nästa månad."], [
          opt(["Pay last month's amounts manually through the bank", "Betala förra månadens belopp manuellt via banken"], "c4", ["People are paid. Overtime and leavers will be wrong until corrected.", "Folk får betalt. Övertid och avslutade anställningar blir fel tills de rättas."], { set: "paidManual", pushback: [
            pb(["Leavers paid again", "Avgångna får lön igen"], ["HR finds that people who left last month would be paid again, and new starters would get nothing. Clawing money back from former staff is slow and unpleasant. Do you send the file as it is, or stop to fix the exceptions and risk missing the bank's cut-off?", "HR upptäcker att personer som slutade förra månaden skulle få lön igen, och att nyanställda inte får något. Att kräva tillbaka pengar av före detta anställda är långsamt och obehagligt. Skickar ni filen som den är, eller stannar ni för att rätta undantagen och riskerar bankens brytpunkt?"]),
            pb(["Tax on a guess", "Skatt på en gissning"], ["{{person.cfo.name}} notes that tax and deductions will also be last month's, so the official reporting will not match what people actually earned. Every payslip will need correcting. Are you prepared to explain that mismatch to staff and auditors afterwards?", "{{person.cfo.name}} påpekar att även skatt och avdrag blir förra månadens, så den officiella redovisningen stämmer inte med vad folk faktiskt tjänat. Varje lönebesked måste rättas. Är ni beredda att förklara den skillnaden för personal och revisorer i efterhand?"]),
            pb(["Outside every control", "Utanför alla kontroller"], ["The file is built from a spreadsheet by hand, outside every normal control. Nobody has checked that the bank accounts in it are current, and one wrong account is someone's whole salary. Who checks it, and how carefully, with hours to the cut-off?", "Filen byggs för hand i ett kalkylark, utanför alla vanliga kontroller. Ingen har kontrollerat att kontonumren i den är aktuella, och ett felaktigt konto är någons hela lön. Vem granskar den, och hur noga, med bara timmar kvar till brytpunkten?"])
          ] }),
          opt(["Delay salaries and tell staff why", "Skjut upp lönerna och berätta varför"], "c4", ["Honest, and painful for everyone living month to month.", "Ärligt, och smärtsamt för alla som lever från månad till månad."], { set: "payDelayed", pushback: [
            pb(["Rent and childcare", "Hyra och barnomsorg"], ["Within an hour HR has messages from staff who cannot pay rent or childcare without tomorrow's salary. Some ask for an advance. If you start paying advances, why not just pay everyone?", "Inom en timme har HR fått meddelanden från anställda som inte kan betala hyra eller barnomsorg utan morgondagens lön. Några ber om förskott. Om ni börjar betala förskott, varför inte bara betala alla?"]),
            pb(["“A breach of terms”", "”Ett avtalsbrott”"], ["Staff representatives say a late salary breaks employment terms whatever the cause, and expect the company to cover overdraft and late fees. Do you accept that cost now, or argue that the delay is the provider's fault?", "Personalens företrädare säger att en sen lön bryter mot anställningsvillkoren oavsett orsak, och väntar sig att företaget står för övertrassering och förseningsavgifter. Tar ni den kostnaden nu, eller hävdar ni att förseningen är leverantörens fel?"]),
            pb(["Others paid on time", "Andra betalade i tid"], ["Word spreads that another company using the same provider paid its staff on time by hand. Your people now ask why their employer couldn't. What do you say when the delay looks like a choice rather than a necessity?", "Det sprids att ett annat företag med samma leverantör betalade sin personal i tid för hand. Era anställda frågar nu varför deras arbetsgivare inte kunde. Vad säger ni när förseningen ser ut som ett val snarare än en nödvändighet?"])
          ] }),
          opt(["Ask the provider to run it from their backup system", "Be leverantören köra lönerna från sitt reservsystem"], "c4", ["Trusts a platform under investigation with your payments.", "Litar på en plattform under utredning med era utbetalningar."], { pushback: [
            pb(["Same team, same platform", "Samma team, samma plattform"], ["{{person.ciso.name}} asks who runs the backup system. The answer: the same team, on partly the same infrastructure, still under investigation. Do you send {{num.payrollTotal|currency}} in salaries through it without knowing what the attacker can reach?", "{{person.ciso.name}} frågar vem som driver reservsystemet. Svaret: samma team, delvis på samma infrastruktur, fortfarande under utredning. Skickar ni löner på {{num.payrollTotal|currency}} genom det utan att veta vad angriparen kommer åt?"]),
            pb(["No promise, no liability", "Inget löfte, inget ansvar"], ["The provider agrees to try, but will not promise the run finishes before the bank's cut-off, and accepts no liability if it doesn't. If it fails, there is no time left for anything else. What is your plan if the answer comes too late?", "Leverantören lovar att försöka, men inte att körningen blir klar före bankens brytpunkt, och tar inget ansvar om den inte blir det. Misslyckas den finns ingen tid kvar till något annat. Vad är er plan om beskedet kommer för sent?"]),
            pb(["Can you trust the copy?", "Går kopian att lita på?"], ["The backup holds its own copy of your payroll data, bank account numbers included. Nobody can yet say whether that copy was touched before the incident was spotted. How would you know salaries are going to the right accounts before the money is gone?", "Reservsystemet har en egen kopia av era lönedata, kontonummer inräknade. Ingen kan ännu säga om den kopian rördes innan incidenten upptäcktes. Hur skulle ni veta att lönerna går till rätt konton innan pengarna är borta?"])
          ] })
        ])
      }),

      pg("c3b", ["The FAQ", "Frågor och svar"], [
        "The provider's public FAQ says there is “no evidence of misuse” and advises customers to “remain calm”. It says nothing about which data was taken.\n\nOn your intranet, a thread has already started: staff are asking whether their bank details are safe and whether they will be paid tomorrow. Managers are forwarding the questions to HR.",
        "Leverantörens offentliga frågor och svar säger att det ”inte finns några tecken på missbruk” och råder kunderna att ”behålla lugnet”. Där står ingenting om vilken data som togs.\n\nPå ert intranät har en tråd redan startat: personalen frågar om deras bankuppgifter är säkra och om de får lön i morgon. Chefer vidarebefordrar frågorna till HR."
      ], {
        choice: ask(["What do you tell staff?", "Vad säger ni till personalen?"], ["Says what is known and not known instead of repeating a provider's reassurance.", "Säger vad som är känt och inte känt i stället för att upprepa leverantörens lugnande besked."], [
          opt(["What you know, what you don't, and what to watch for", "Vad ni vet, vad ni inte vet och vad de ska vara uppmärksamma på"], "c4", ["Builds trust even without answers.", "Bygger förtroende även utan svar."], { set: "staffTold", pushback: [
            pb(["“Why don't you know?”", "”Varför vet ni inte?”"], ["Within minutes, replies ask the obvious: if you don't know what was taken, why not? Some staff read your honesty as incompetence. Do you keep saying “we don't know yet”, or start guessing to sound in control?", "Inom några minuter kommer den självklara frågan: om ni inte vet vad som togs, varför vet ni inte det? En del läser er ärlighet som inkompetens. Fortsätter ni säga ”vi vet inte ännu”, eller börjar ni gissa för att verka ha kontroll?"]),
            pb(["The provider objects", "Leverantören protesterar"], ["The provider's account manager complains that your message contradicts their “no evidence of misuse” line and is causing alarm. They ask you to align with their wording. Do you hold your own message, or soften it to keep their cooperation?", "Leverantörens kundansvarige klagar på att ert meddelande motsäger deras ”inga tecken på missbruk” och skapar oro. De ber er hålla er till deras formulering. Står ni fast vid ert budskap, eller mildrar ni det för att behålla samarbetet?"]),
            pb(["“Is this real?”", "”Är det här äkta?”"], ["Telling staff what to watch for gives them a job you must now support. HR's inbox fills with forwarded emails asking “is this real?”. Who answers them all, and how fast, with HR already swamped?", "Att säga åt personalen vad de ska vara uppmärksamma på ger dem ett uppdrag som ni nu måste stötta. HR:s inkorg fylls av vidarebefordrade mejl med frågan ”är det här äkta?”. Vem svarar på alla, och hur snabbt, när HR redan är överbelastat?"])
          ] }),
          opt(["Repeat the provider's line", "Upprepa leverantörens formulering"], "c4", ["Ties your credibility to theirs.", "Knyter er trovärdighet till deras."], { pushback: [
            pb(["Not the same thing", "Inte samma sak"], ["{{person.dpo.name}} points out that “no evidence of misuse” is not the same as “nothing was taken”. If the provider's line turns out wrong, your name is on it too. Are you ready to retract it in front of your own staff?", "{{person.dpo.name}} påpekar att ”inga tecken på missbruk” inte är samma sak som ”inget togs”. Visar sig leverantörens formulering vara fel står ert namn också på den. Är ni beredda att ta tillbaka den inför er egen personal?"]),
            pb(["Copied word for word", "Kopierat ord för ord"], ["The intranet thread reacts within minutes: “this is the provider's text, word for word”. People ask whether management knows anything at all. Do you add something of your own, or let the copied statement stand?", "Tråden på intranätet reagerar inom några minuter: ”det här är leverantörens text, ord för ord”. Folk undrar om ledningen vet något alls. Lägger ni till något eget, eller låter ni det kopierade beskedet stå?"]),
            pb(["Managers won't repeat it", "Chefer vägrar upprepa det"], ["Managers who forwarded questions to HR get the same reassurance back. Two of them say they will not tell their teams to “remain calm” without facts. Do you insist they pass on the line, or let them say what they think?", "Chefer som skickat frågor till HR får samma lugnande besked tillbaka. Två av dem säger att de inte tänker be sina grupper ”behålla lugnet” utan fakta. Kräver ni att de för vidare formuleringen, eller låter ni dem säga vad de tycker?"])
          ] })
        ])
      }),

      pg("c4", ["Staff are asking", "Personalen frågar"], [
        "The news has spread through the company. The union representative writes to {{person.hr.name}}: members want to know whether they should change bank accounts, and whether they will be paid on time.\n\nThey want an answer they can pass on today. Silence from HR is already being read as bad news.",
        "Nyheten har spridit sig i företaget. Den fackliga representanten skriver till {{person.hr.name}}: medlemmarna vill veta om de ska byta bankkonto och om de får lön i tid.\n\nDe vill ha ett svar som de kan föra vidare i dag. Tystnad från HR tolkas redan som dåliga nyheter."
      ], {
        variants: [
          vr("staffTold", [
            "Because staff were told early and honestly, the union representative's questions are practical rather than angry: should members change bank accounts, and what should they watch out for?\n\nThey want an answer they can pass on today, and they offer to help spread it.",
            "Eftersom personalen informerades tidigt och ärligt är den fackliga representantens frågor praktiska snarare än arga: ska medlemmarna byta bankkonto, och vad ska de vara uppmärksamma på?\n\nDe vill ha ett svar som de kan föra vidare i dag, och de erbjuder sig att hjälpa till att sprida det."
          ]),
          vr("payDelayed", [
            "Payday came and went without salaries. The union representative is angry: nobody has explained when the money will come, and some members cannot pay their rent.\n\nThey want answers today, and they are talking about going to the press if they do not get them.",
            "Lönedagen kom och gick utan löner. Den fackliga representanten är arg: ingen har förklarat när pengarna kommer, och en del medlemmar kan inte betala hyran.\n\nDe vill ha svar i dag, och de pratar om att gå till pressen om de inte får det."
          ], ["Because salaries were delayed, this is now an employment issue too.", "Eftersom lönerna försenades är det nu också en arbetsrättslig fråga."])
        ],
        injects: [
          inj("b2-2", 240, "email", "employee", "medium", "confirmed", [
            "Members are worried. Is our data stolen? Should we change bank accounts? Will we be paid on time? We need an answer we can pass on today.",
            "Medlemmarna är oroliga. Är våra uppgifter stulna? Ska vi byta bankkonto? Får vi lön i tid? Vi behöver ett svar vi kan föra vidare i dag."
          ], { headline: ["From the union representative", "Från den fackliga representanten"], meta: { from: "union rep", subject: L(["Payroll incident: questions", "Löneincidenten: frågor"]) }, tests: ["lo3"] })
        ],
        choice: ask(["How do you answer staff?", "Hur svarar ni personalen?"], ["One clear message to everyone, today, with practical advice.", "Ett tydligt besked till alla, i dag, med praktiska råd."], [
          opt(["All-staff message today with fraud advice", "Meddelande till all personal i dag med råd om bedrägerier"], "l2", ["Consistent and fast. Commits you to updates.", "Enhetligt och snabbt. Förpliktar till uppdateringar."], { set: "staffTold", pushback: [
            pb(["Now they expect updates", "Nu väntar de på uppdateringar"], ["Your message promised updates, and staff now expect one every time the news moves. Each one must be cleared by legal, HR and security before it goes out. Who owns the next update, and when is it due?", "Ert meddelande lovade uppdateringar, och nu väntar sig personalen en varje gång nyhetsläget ändras. Varje gång måste juristen, HR och säkerhet godkänna texten. Vem äger nästa uppdatering, och när ska den komma?"]),
            pb(["Change accounts or not?", "Byta konto eller inte?"], ["The union representative replies: the message still doesn't say whether members should change bank accounts. Saying yes sends hundreds of people to their banks; saying no could be wrong. Which answer do you give without knowing what was taken?", "Den fackliga representanten svarar: meddelandet säger fortfarande inte om medlemmarna ska byta bankkonto. Ett ja skickar hundratals personer till sina banker; ett nej kan vara fel. Vilket svar ger ni utan att veta vad som togs?"]),
            pb(["Not everyone reads email", "Alla läser inte mejl"], ["Staff without a desk or work computer rarely open company email, and they are often the ones living month to month. Your all-staff message has not reached them. How do you get the same words to people who are not at a screen?", "Anställda utan skrivbord eller jobbdator öppnar sällan företagets mejl, och det är ofta de som lever från lön till lön. Ert meddelande till all personal har inte nått dem. Hur får ni samma besked till dem som inte sitter vid en skärm?"])
          ] }),
          opt(["Wait until the facts are clear", "Vänta tills fakta är klara"], "l2", ["Rumours fill the gap.", "Rykten fyller tomrummet."], { pushback: [
            pb(["The union goes first", "Facket går först"], ["The union representative says that if HR has nothing by the end of the day, the union will send members its own advice. Their version may be more alarming than yours. Are you willing to let someone else become the source staff trust?", "Den fackliga representanten säger att om HR inte har något i slutet av dagen skickar facket egna råd till medlemmarna. Deras version kan bli mer alarmerande än er. Är ni beredda att låta någon annan bli den källa personalen litar på?"]),
            pb(["Silence is the message", "Tystnaden är beskedet"], ["A manager reports that staff have concluded “it must be bad if they won't say”. Every hour of quiet confirms the worst version. What exactly are you waiting for, and when will you have it?", "En chef berättar att personalen dragit slutsatsen ”det måste vara illa om de inte säger något”. Varje tyst timme bekräftar den värsta versionen. Vad är det exakt ni väntar på, och när har ni det?"]),
            pb(["Facts may take weeks", "Fakta kan dröja i veckor"], ["{{person.ciso.name}} warns that clear facts may take weeks from a provider still investigating. “Until it's clear” could mean saying nothing until long after payday. Is there a date by which you speak regardless?", "{{person.ciso.name}} varnar för att tydliga fakta kan dröja veckor från en leverantör som fortfarande utreder. ”Tills det är klart” kan betyda tystnad långt efter lönedagen. Finns det ett datum då ni talar oavsett?"])
          ] }),
          opt(["Let managers brief their teams", "Låt cheferna informera sina grupper"], "l2", ["Personal, but every manager tells a different story.", "Personligt, men varje chef berättar en egen version."], { pushback: [
            pb(["Five different stories", "Fem olika berättelser"], ["By afternoon HR has heard five versions: one team was told salaries are safe, another that bank details were stolen. Staff compare notes over lunch. Do you now send a central message that contradicts some of your own managers?", "På eftermiddagen har HR hört fem versioner: en grupp har fått höra att lönerna är säkra, en annan att bankuppgifter stulits. Personalen jämför vid lunchen. Skickar ni nu ett centralt besked som motsäger några av era egna chefer?"]),
            pb(["Managers push it back", "Cheferna skickar tillbaka det"], ["Some managers say they cannot answer questions about personal data they know nothing about, and send their teams to HR. Others are affected themselves and upset. Do you make them brief anyway, or take it back to the centre?", "En del chefer säger att de inte kan svara på frågor om personuppgifter de inte vet något om, och skickar sina grupper till HR. Andra är själva drabbade och upprörda. Tvingar ni dem att informera ändå, eller tar ni tillbaka det centralt?"]),
            pb(["The union asked for one answer", "Facket bad om ett svar"], ["The union representative asked HR for one answer to pass on. Leaving it to managers looks like dodging the question. How do you answer the union directly, now that you have chosen not to speak centrally?", "Den fackliga representanten bad HR om ett svar att föra vidare. Att lämna det till cheferna ser ut som att ni smiter undan frågan. Hur svarar ni facket direkt, nu när ni valt att inte gå ut centralt?"])
          ] })
        ])
      }),

      pg("l2", ["Change my bank account", "Byt mitt bankkonto"], [
        "HR's inbox fills with something new: {{num.fakeChanges}} emails asking to change the bank account a salary is paid into.\n\nSome come from worried staff who want to move their money. Others only look like they do, sent from personal addresses nobody recognises. Telling them apart by email is almost impossible.",
        "HR:s inkorg fylls av något nytt: {{num.fakeChanges}} mejl med begäran om att byta det bankkonto som lönen betalas till.\n\nEn del kommer från oroliga anställda som vill flytta sina pengar. Andra ser bara ut att göra det, skickade från privata adresser som ingen känner igen. Att skilja dem åt via mejl är nästan omöjligt."
      ], {
        long: true,
        skipTo: "c5",
        choice: ask(["What do you do with bank-detail changes?", "Vad gör ni med ändringar av bankuppgifter?"], ["Freezes changes and verifies through a known channel.", "Fryser ändringar och verifierar via en känd kanal."], [
          opt(["Freeze all changes; verify each one by phone", "Frys alla ändringar; verifiera var och en per telefon"], "c5", ["Slower for genuine requests, closes the obvious fraud.", "Långsammare för äkta ärenden, stänger det uppenbara bedrägeriet."], { set: "changesFrozen", pushback: [
            pb(["Which number do you call?", "Vilket nummer ringer ni?"], ["The phone numbers HR would call come from the same personnel records that may be in someone else's hands. A fraudster could have supplied a number too. How do you know the person who answers is really the employee?", "Telefonnumren som HR skulle ringa kommer från samma personaluppgifter som kan finnas hos någon annan. En bedragare kan ha lämnat ett nummer också. Hur vet ni att den som svarar verkligen är den anställda?"]),
            pb(["A genuine request stuck", "Ett äkta ärende fastnar"], ["An employee whose bank told them to move accounts after a fraud alert is stuck in the freeze, with salary still heading to the compromised account. They are furious and copying in the union. Do you make an exception, and how do you stop it becoming the loophole?", "En anställd som fått rådet av sin bank att byta konto efter en bedrägerivarning har fastnat i frysningen, och lönen går fortfarande till det utsatta kontot. Hen är rasande och har kopierat in facket. Gör ni ett undantag, och hur hindrar ni att det blir kryphålet?"]),
            pb(["Two people, many calls", "Två personer, många samtal"], ["HR has two people free for verification calls, and requests arrive faster than they can phone. Each one waits days. How long can the freeze last before it becomes a crisis of its own?", "HR har två personer lediga för verifieringssamtal, och ärendena kommer in snabbare än de hinner ringa. Varje ärende väntar i dagar. Hur länge kan frysningen pågå innan den blir en kris i sig?"])
          ] }),
          opt(["Process them as normal", "Hantera dem som vanligt"], "c5", ["Some salaries will go to criminals.", "En del löner kommer att gå till kriminella."], { pushback: [
            pb(["“I never asked”", "”Jag har aldrig bett om det”"], ["An employee calls: they never asked to change their account, yet HR has already updated it. Their salary would have gone to a stranger. Do you stop and check every change you have processed, admitting the routine was wrong?", "En anställd ringer: hen har aldrig bett om att byta konto, men HR har redan ändrat det. Lönen skulle ha gått till en främling. Stoppar ni och kontrollerar varje ändring ni gjort, och erkänner att rutinen var fel?"]),
            pb(["The bank calls", "Banken ringer"], ["The bank's fraud team calls about several brand-new accounts set to receive your salaries. They ask whether you verified the changes. What do you tell them?", "Bankens bedrägerigrupp ringer om flera helt nya konton som ska ta emot era löner. De frågar om ni verifierade ändringarna. Vad svarar ni?"]),
            pb(["Paying twice", "Betala två gånger"], ["{{person.legal.name}} asks: if a salary goes to a fraudster because you acted on an unverified email, does the company owe the employee again? The likely answer is yes. Are you ready to pay some salaries twice?", "{{person.legal.name}} frågar: om en lön går till en bedragare för att ni agerade på ett overifierat mejl, är företaget då skyldigt den anställda lönen igen? Troligen ja. Är ni beredda att betala vissa löner två gånger?"])
          ] })
        ])
      }),

      pg("c5", ["Payday phishing", "Nätfiske på lönedagen"], [
        "The fraudsters have noticed the news too. Emails with your logo are reaching staff: “confirm your details to receive this month's salary”, with a link to a portal that looks exactly like your HR system.\n\nSeveral people have already clicked. The site asks for bank ID login and account numbers.",
        "Bedragarna har också sett nyheterna. Mejl med er logotyp når personalen: ”bekräfta dina uppgifter för att få månadens lön”, med en länk till en portal som ser exakt ut som ert HR-system.\n\nFlera personer har redan klickat. Sajten ber om inloggning med bank-id och kontonummer."
      ], {
        variants: [
          vr("changesFrozen", [
            "The fraudsters have noticed the news too. Emails with your logo invite staff to “confirm your details” on a portal that looks exactly like your HR system.\n\nThe freeze is already paying off: two fake bank-account changes are stuck in it, waiting for a phone call that will never come. But the phishing site is still live, and people are clicking.",
            "Bedragarna har också sett nyheterna. Mejl med er logotyp uppmanar personalen att ”bekräfta sina uppgifter” på en portal som ser exakt ut som ert HR-system.\n\nFrysningen lönar sig redan: två falska bankkontoändringar har fastnat i den och väntar på ett telefonsamtal som aldrig kommer. Men nätfiskesajten är fortfarande uppe, och folk klickar."
          ], ["Because changes were frozen, the first fraud attempts failed.", "Eftersom ändringarna frystes misslyckades de första bedrägeriförsöken."]),
          vr("paidManual", [
            "The manual payment went out and most people were paid, though some amounts were wrong. Now the fraudsters are using that: emails with your logo offer a “salary correction” to anyone who confirms their details on a look-alike portal.\n\nIt is the most believable lie they could tell, because some corrections really are needed.",
            "Den manuella utbetalningen gick iväg och de flesta fick lön, även om en del belopp blev fel. Nu utnyttjar bedragarna det: mejl med er logotyp erbjuder en ”lönekorrigering” till den som bekräftar sina uppgifter på en efterliknad portal.\n\nDet är den mest trovärdiga lögn de kunde komma på, eftersom en del korrigeringar faktiskt behövs."
          ])
        ],
        injects: [
          inj("b2-3", 300, "phishingEmail", "attacker", "high", "confirmed", [
            "Due to a technical issue with this month's payroll, please confirm your bank details within 24 hours to receive your salary.",
            "På grund av ett tekniskt fel med månadens lön, bekräfta dina bankuppgifter inom 24 timmar för att få din lön."
          ], { headline: ["Action required: confirm your salary details", "Åtgärd krävs: bekräfta dina löneuppgifter"], meta: { from: "payroll@{{asset.lookalikeDomain}}", subject: L(["Confirm your salary details", "Bekräfta dina löneuppgifter"]) }, tests: ["lo4"] })
        ],
        choice: ask(["How do you respond to the phishing?", "Hur hanterar ni nätfisket?"], ["Warns staff fast through a channel that doesn't look like the phishing.", "Varnar personalen snabbt via en kanal som inte liknar nätfisket."], [
          opt(["Warn staff, block the domain, report the site", "Varna personalen, blockera domänen, anmäl sidan"], "l3", ["Standard and effective if it happens within the hour.", "Standard och effektivt om det sker inom en timme."], { pushback: [
            pb(["The warning looks like phishing", "Varningen ser ut som nätfiske"], ["Your warning carries the same logo and lands in the same inbox as the fake. Some staff ignore it as one more suspicious email; others click its links to check. How do you make a real warning look different from the fake?", "Er varning har samma logotyp och hamnar i samma inkorg som det falska mejlet. En del ignorerar den som ännu ett misstänkt mejl; andra klickar på länkarna för att kontrollera. Hur får ni en äkta varning att se annorlunda ut än den falska?"]),
            pb(["Already entered", "Redan inmatat"], ["People who clicked before your warning ask what to do now: their bank ID login and account numbers are already in the fake site. Some are too embarrassed to say they clicked. How do you reach them, and what do you offer?", "De som klickade före er varning undrar vad de ska göra nu: deras bank-id-inloggning och kontonummer finns redan på den falska sajten. En del skäms för mycket för att säga att de klickat. Hur når ni dem, och vad erbjuder ni?"]),
            pb(["A new domain appears", "En ny domän dyker upp"], ["Within an hour of your report the site is down, and a near-identical one appears under a new name. Blocking one domain at a time is a race you are losing. Do you keep chasing domains, or change what you tell staff?", "Inom en timme efter er anmälan är sajten nere, och en nästan likadan dyker upp under ett nytt namn. Att blockera en domän i taget är en kapplöpning ni förlorar. Fortsätter ni jaga domäner, eller ändrar ni vad ni säger till personalen?"])
          ] }),
          opt(["Leave it to IT security as a routine case", "Lämna det till IT-säkerhet som ett rutinärende"], "l3", ["Routine speed is too slow on payday.", "Rutintempo är för långsamt på lönedagen."], { pushback: [
            pb(["Behind the backlog", "Längst bak i kön"], ["IT security logs the case behind a backlog of routine tickets and expects to look at it tomorrow. Meanwhile the clicks keep coming. Do you keep it routine, or pull the team off everything else today?", "IT-säkerhet lägger ärendet bakom en kö av rutinärenden och räknar med att titta på det i morgon. Under tiden fortsätter klicken. Behåller ni det som rutin, eller drar ni teamet från allt annat i dag?"]),
            pb(["Money already gone", "Pengar redan borta"], ["An employee reports money missing from their account after logging in to the fake portal. To them, this was never routine. What do you tell them about why the company didn't warn people sooner?", "En anställd rapporterar att pengar saknas på kontot efter inloggning på den falska portalen. För hen var det här aldrig rutin. Vad säger ni om varför företaget inte varnade tidigare?"]),
            pb(["HR is guessing", "HR gissar"], ["HR is getting dozens of “is this real?” calls, and without guidance some staff are being told it is “probably fine”. A routine case gives them no script. Who tells HR what to say, today?", "HR får dussintals samtal med frågan ”är det här äkta?”, och utan vägledning får en del höra att det ”säkert är okej”. Ett rutinärende ger dem inget manus. Vem talar om för HR vad de ska säga, i dag?"])
          ] }),
          opt(["Cancel the manual payment file: the provider now promises payroll by 15:00", "Avbryt den manuella betalfilen: leverantören lovar nu lönen till klockan 15"], "l3", ["Reverses your early fallback on the provider's word alone.", "Upphäver er tidiga reservlösning enbart på leverantörens ord."], { requires: "manualPrep", set: "manualCancelled", effects: { trust: -1 }, pushback: [
            pb(["One email of promise", "Ett löfte i ett mejl"], ["The promise is a single email from the account manager, with no technical detail, from a platform still under investigation. If it slips, your manual file is gone and the bank's cut-off has passed. What is your plan if the provider misses its own deadline?", "Löftet är ett enda mejl från kundansvarige, utan tekniska detaljer, från en plattform som fortfarande utreds. Om det spricker är er manuella fil borta och bankens brytpunkt passerad. Vad är er plan om leverantören missar sin egen tidsgräns?"]),
            pb(["Finance's work thrown away", "Ekonomis arbete slängs"], ["{{person.cfo.name}} reminds you that finance has checked the manual file and it is ready to send. Cancelling it throws away the only payment you control. Why take it off the table on the provider's word alone?", "{{person.cfo.name}} påminner om att ekonomi har granskat den manuella filen och att den är klar att skicka. Att avbryta den kastar bort den enda utbetalning ni själva styr. Varför plocka bort den enbart på leverantörens ord?"]),
            pb(["Every hour helps the fraudsters", "Varje timme hjälper bedragarna"], ["Fake “confirm your salary” emails are already reaching staff. If the provider's run is late, every hour without pay makes those emails more convincing. Are you willing to give the fraudsters that extra time?", "Falska mejl om att ”bekräfta din lön” når redan personalen. Om leverantörens körning blir sen gör varje timme utan lön mejlen mer trovärdiga. Är ni beredda att ge bedragarna den extra tiden?"])
          ] })
        ])
      }),

      pg("l3", ["Personal identity numbers", "Personnummer"], [
        "The provider's written statement finally arrives. Personal identity numbers and bank account numbers for all your employees were in the stolen data, together with home addresses.\n\nThat combination is what identity thieves need to open loans and accounts in someone else's name. Staff will ask what you are doing to protect them.",
        "Leverantörens skriftliga redogörelse kommer till slut. Personnummer och bankkontonummer för alla era anställda fanns i den stulna datan, tillsammans med hemadresser.\n\nDen kombinationen är precis vad identitetstjuvar behöver för att ta lån och öppna konton i någon annans namn. Personalen kommer att fråga vad ni gör för att skydda dem."
      ], {
        long: true,
        skipTo: "c6",
        chart: { id: "b2-scope", type: "kpi", title: L(["Confirmed in the stolen data", "Bekräftat i den stulna datan"]), data: kpi([
          { id: "k1", label: ["Employees", "Anställda"], value: (v, ctx) => ctx.org.headcount, tone: "danger" },
          { id: "k2", label: ["Months of payslips", "Månader av lönebesked"], value: (v) => v.payslipMonths, tone: "warn" }
        ]) },
        choice: ask(["What do you offer staff?", "Vad erbjuder ni personalen?"], ["Gives practical protection, not only information.", "Ger praktiskt skydd, inte bara information."], [
          opt(["Identity-protection support and a helpline", "Stöd för id-skydd och en stödlinje"], "c6", ["Costs money, shows care, reduces real harm.", "Kostar pengar, visar omtanke, minskar verklig skada."], { pushback: [
            pb(["Who answers the helpline?", "Vem svarar i stödlinjen?"], ["The helpline needs people who can explain credit freezes and bank fraud, in the evenings too. HR has nobody who can, and an external service takes a week to set up. What do staff get in the meantime?", "Stödlinjen behöver folk som kan förklara kreditspärrar och bankbedrägerier, även på kvällarna. HR har ingen som kan, och en extern tjänst tar en vecka att få på plats. Vad får personalen under tiden?"]),
            pb(["Families too?", "Familjen också?"], ["Staff ask whether partners are covered, since home addresses were taken and fraud letters arrive at the whole household. Including families multiplies the cost; excluding them looks cold. Where do you draw the line?", "Anställda frågar om partner omfattas, eftersom hemadresser togs och bedrägeribrev kommer till hela hushållet. Att ta med familjerna mångdubblar kostnaden; att utesluta dem verkar kallt. Var drar ni gränsen?"]),
            pb(["Shouldn't the provider pay?", "Borde inte leverantören betala?"], ["{{person.supplierManager.name}} argues that the provider should fund the support, and that paying for it yourselves weakens any later claim. Getting them to agree could take weeks. Do you pay now and argue later, or hold out?", "{{person.supplierManager.name}} menar att leverantören borde betala stödet, och att det försvagar ett senare krav om ni betalar själva. Att få dem att gå med på det kan ta veckor. Betalar ni nu och tar striden sen, eller håller ni emot?"])
          ] }),
          opt(["No extra measures beyond the message", "Inga åtgärder utöver meddelandet"], "c6", ["Cheaper today. Staff will remember.", "Billigare i dag. Personalen kommer att minnas det."], { pushback: [
            pb(["Put it in writing", "Skriv det på papper"], ["The union representative points out that staff now face loans taken out in their names, and the company's answer is a message. They ask for the decision in writing. Will you put “no extra measures” in a letter to the union?", "Den fackliga representanten påpekar att personalen nu riskerar lån i sitt namn, och att företagets svar är ett meddelande. Facket vill ha beslutet skriftligt. Skriver ni ”inga ytterligare åtgärder” i ett brev till facket?"]),
            pb(["The first credit check", "Den första kreditupplysningen"], ["An employee reports a credit check in their name at a lender they have never used. They ask what the company will do about it. What do you say now that the harm is no longer hypothetical?", "En anställd rapporterar en kreditupplysning i sitt namn hos en långivare hen aldrig använt. Hen frågar vad företaget tänker göra. Vad säger ni nu när skadan inte längre är hypotetisk?"]),
            pb(["The sentence in the report", "Meningen i anmälan"], ["{{person.dpo.name}} notes that any report to {{reg.dpaShort}} must describe the measures taken to limit harm to the people affected. “None beyond a message” is what you would have to write. Are you comfortable with that sentence being read?", "{{person.dpo.name}} påpekar att en anmälan till {{reg.dpaShort}} ska beskriva vilka åtgärder som vidtagits för att begränsa skadan för de berörda. ”Inga utöver ett meddelande” är vad ni skulle behöva skriva. Är ni bekväma med att den meningen läses?"])
          ] })
        ])
      }),

      pg("c6", ["Whose 72 hours?", "Vems 72 timmar?"], [
        "{{person.dpo.name}} sets out the legal position. You are the controller of your employees' data; the provider is only your processor.\n\nThe duty to notify {{reg.dpaShort}} within 72 hours is therefore yours, whatever the provider does or says. The clock started when you learned of the breach this morning.",
        "{{person.dpo.name}} går igenom det rättsliga läget. Ni är personuppgiftsansvariga för de anställdas uppgifter; leverantören är bara ert biträde.\n\nSkyldigheten att anmäla till {{reg.dpaShort}} inom 72 timmar är därför er, oavsett vad leverantören gör eller säger. Klockan började gå när ni fick veta om intrånget i morse."
      ], {
        discuss: [q("What do you write in a notification when the facts come from someone else?", "Vad skriver ni i en anmälan när fakta kommer från någon annan?", ["dpo", "legal"])],
        choice: ask(["How do you handle notification?", "Hur hanterar ni anmälan?"], ["Notifies as controller within 72 hours, based on what the processor has confirmed.", "Anmäler som personuppgiftsansvarig inom 72 timmar, utifrån det biträdet har bekräftat."], [
          opt(["Notify {{reg.dpaShort}} yourselves now", "Anmäl till {{reg.dpaShort}} själva nu"], "c7", ["Meets your own duty. The provider may not like your wording.", "Uppfyller er egen skyldighet. Leverantören kanske inte gillar formuleringarna."], { set: "notified", pushback: [
            pb(["Someone else's facts", "Någon annans fakta"], ["Every fact in your notification comes from a provider still investigating, and you cannot check any of it yourselves. Your name goes on the report all the same. Do you sign a report to the authority built on someone else's word, or hold it for a few hours to test it?", "Varje uppgift i er anmälan kommer från en leverantör som fortfarande utreder, och ni kan inte kontrollera något av det själva. Ert namn står ändå på anmälan. Skriver ni under en anmälan till myndigheten som bygger på någon annans ord, eller väntar ni några timmar för att pröva den?"]),
            pb(["The provider is angry", "Leverantören är arg"], ["The account manager calls: your notification names them before their own statement and was not coordinated. They hint that help with payroll may become “more formal” from now on. Do you stand by your timing if that help slows down?", "Kundansvarige ringer: er anmälan pekar ut dem före deras eget uttalande och samordnades inte. Hen antyder att hjälpen med lönerna kan bli ”mer formell” framöver. Står ni fast vid er tidpunkt om den hjälpen går långsammare?"]),
            pb(["Who decided?", "Vem beslutade?"], ["{{person.ceo.name}} learns that a notice to the authority is going out without having been raised in the management team, and asks who decided. Nobody can point to a written decision. Who has the mandate to notify, and where is that recorded?", "{{person.ceo.name}} får veta att en anmälan till myndigheten går iväg utan att ha tagits upp i ledningsgruppen, och frågar vem som beslutade. Ingen kan peka på ett skriftligt beslut. Vem har mandat att anmäla, och var står det?"])
          ] }),
          opt(["Wait for the provider to notify for everyone", "Vänta på att leverantören anmäler för alla"], "c7", ["Their notification does not discharge yours.", "Deras anmälan befriar inte er från er skyldighet."], { set: "waitedProvider", pushback: [
            pb(["The DPO puts it in writing", "Dataskyddsombudet skriver ned det"], ["{{person.dpo.name}} puts it in an email to management: the provider's notification covers the provider, not you as controller. Waiting means relying on a company you don't control to meet your deadline. What do you do if they haven't notified when your 72 hours run out?", "{{person.dpo.name}} skriver det i ett mejl till ledningen: leverantörens anmälan gäller leverantören, inte er som personuppgiftsansvariga. Att vänta är att lita på att ett företag ni inte styr håller er frist. Vad gör ni om de inte har anmält när era 72 timmar har gått?"]),
            pb(["“When the investigation allows”", "”När utredningen tillåter”"], ["You ask the provider when it will notify. The answer is “when the investigation allows”. That is not a date. Do you keep waiting on an answer with no date while your own clock runs?", "Ni frågar leverantören när den tänker anmäla. Svaret är ”när utredningen tillåter”. Det är inget datum. Fortsätter ni vänta på ett svar utan datum medan er egen klocka går?"]),
            pb(["“Has it been reported?”", "”Har det anmälts?”"], ["The union representative asks whether the authority has been told about the breach of members' data. The honest answer is “not by us”. How do you explain that to the people whose data it is?", "Den fackliga representanten frågar om myndigheten har fått veta om intrånget i medlemmarnas uppgifter. Det ärliga svaret är ”inte av oss”. Hur förklarar ni det för dem vars uppgifter det gäller?"])
          ] }),
          opt(["Notify only once misuse is confirmed", "Anmäl först när missbruk bekräftats"], "c7b", ["Wrong test: the duty is about risk, not proof of misuse.", "Fel måttstock: skyldigheten handlar om risk, inte bevis på missbruk."], { pushback: [
            pb(["Misuse may never show", "Missbruk kanske aldrig syns"], ["{{person.ciso.name}} points out that stolen identity data is often used months later, if at all, and you may never hear of it. Your trigger may never fire. How long will you wait for proof that may not come?", "{{person.ciso.name}} påpekar att stulna identitetsuppgifter ofta används månader senare, om alls, och att ni kanske aldrig får höra om det. Er utlösare kanske aldrig slår till. Hur länge väntar ni på bevis som kanske aldrig kommer?"]),
            pb(["Not the law's test", "Inte lagens måttstock"], ["{{person.legal.name}} reads the rule aloud: the duty applies when a breach is likely to put people at risk, not when misuse is proven. Your test is not the law's. Do you still wait, against your own lawyer's reading?", "{{person.legal.name}} läser regeln högt: skyldigheten gäller när ett intrång sannolikt innebär en risk för människor, inte när missbruk är bevisat. Er måttstock är inte lagens. Väntar ni ändå, mot er egen jurists tolkning?"]),
            pb(["Is phishing misuse?", "Är nätfisket missbruk?"], ["Staff have already received phishing emails exploiting the incident. Someone asks whether that counts as misuse. If it does, your condition was met hours ago. Who decides what counts, and is it written down?", "Personalen har redan fått nätfiskemejl som utnyttjar incidenten. Någon frågar om det räknas som missbruk. Gör det det var ert villkor uppfyllt för flera timmar sedan. Vem avgör vad som räknas, och står det någonstans?"])
          ] }),
          opt(["Name and shame the provider on social media", "Hänga ut leverantören i sociala medier"], "x1", ["Feels good for an hour.", "Känns bra i en timme."], { pushback: [
            pb(["Comms says no", "Kommunikation säger nej"], ["{{person.comms.name}} warns that a public attack on your own supplier becomes the story, and journalists will then ask what you did to protect staff data. Do you post anyway, and who answers when they call?", "{{person.comms.name}} varnar för att ett offentligt angrepp på er egen leverantör blir nyheten, och att journalister då frågar vad ni gjorde för att skydda personalens uppgifter. Publicerar ni ändå, och vem svarar när de ringer?"]),
            pb(["You still need them", "Ni behöver dem fortfarande"], ["{{supplier.vendor}} still runs your payroll, and you have no other system. Shaming them in public while you depend on them could cost their cooperation. What happens to next month's salaries if they stop helping?", "{{supplier.vendor}} sköter fortfarande era löner, och ni har inget annat system. Att hänga ut dem offentligt medan ni är beroende av dem kan kosta samarbetet. Vad händer med nästa månads löner om de slutar hjälpa till?"]),
            pb(["Can you prove it?", "Kan ni bevisa det?"], ["{{person.legal.name}} asks what evidence you have for each claim in the post. So far, everything you know comes from the provider's own vague statements. Can you stand behind every word if they answer back?", "{{person.legal.name}} frågar vilka belägg ni har för varje påstående i inlägget. Hittills kommer allt ni vet från leverantörens egna vaga uttalanden. Kan ni stå för varje ord om de svarar?"])
          ] })
        ])
      }),

      pg("c7b", ["The provider's lawyer", "Leverantörens jurist"], [
        "Before you notify, the provider's lawyer calls. They ask politely but firmly: please do not notify anyone before their own public statement tomorrow evening.\n\nThey say an early notice from a customer could “compromise the investigation”. Tomorrow evening is after your 72 hours run out.",
        "Innan ni anmäler ringer leverantörens jurist. Hen ber artigt men bestämt: anmäl inte till någon innan deras eget offentliga uttalande i morgon kväll.\n\nHen säger att en tidig anmälan från en kund kan ”äventyra utredningen”. I morgon kväll är efter att era 72 timmar har gått ut."
      ], {
        choice: ask(["Do you agree to wait?", "Går ni med på att vänta?"], ["Keeps its own legal duties regardless of a supplier's preferences.", "Håller fast vid sina egna rättsliga skyldigheter oavsett leverantörens önskemål."], [
          opt(["No. Notify within your own deadline", "Nej. Anmäl inom er egen tidsfrist"], "c7", ["Correct, and it strains the relationship.", "Rätt, och det sätter relationen på prov."], { set: "notified", pushback: [
            pb(["“Against the investigation”", "”Mot utredningen”"], ["The lawyer says that if you notify early, they will record that you “acted against the investigation's interests”. They don't say what that means. Do you notify anyway, and how do you document why?", "Juristen säger att om ni anmäler tidigt kommer de att notera att ni ”agerade mot utredningens intressen”. Vad det innebär säger hen inte. Anmäler ni ändå, och hur dokumenterar ni varför?"]),
            pb(["Two different stories", "Två olika versioner"], ["Notifying now means describing a breach the provider won't yet discuss. Your report will be thin, and their statement tomorrow evening may say something different. Are you ready to defend a notification that doesn't match theirs?", "Att anmäla nu betyder att beskriva ett intrång som leverantören ännu inte vill prata om. Er anmälan blir tunn, och deras uttalande i morgon kväll kan säga något annat. Är ni beredda att försvara en anmälan som inte stämmer med deras?"]),
            pb(["Payroll help at risk", "Lönehjälpen i fara"], ["Finance still needs the provider to produce correct figures for this month's salaries. Going against their lawyer's request could slow that help. Which matters more this week: your deadline or your payroll?", "Ekonomi behöver fortfarande leverantören för att få fram rätt underlag till månadens löner. Att gå emot deras jurist kan göra hjälpen långsammare. Vad väger tyngst den här veckan: er frist eller era löner?"])
          ] }),
          opt(["Yes, wait for their statement", "Ja, vänta på deras uttalande"], "c7", ["Their timeline is now your compliance problem.", "Deras tidsplan är nu ert efterlevnadsproblem."], { set: "waitedProvider", pushback: [
            pb(["Late by design", "Sent med flit"], ["{{person.dpo.name}} confirms in writing that the provider's statement falls after your 72 hours. The authority will ask why you notified late. Is “the supplier's lawyer asked us to” an answer you are willing to give?", "{{person.dpo.name}} bekräftar skriftligt att leverantörens uttalande kommer efter era 72 timmar. Myndigheten kommer att fråga varför ni anmälde för sent. Är ”leverantörens jurist bad oss” ett svar ni är beredda att ge?"]),
            pb(["Nothing in writing", "Inget skriftligt"], ["You ask the lawyer to confirm the request in writing. They decline: it was “just a request”. If anything goes wrong, there is no record they ever asked. Do you still wait on the strength of a phone call?", "Ni ber juristen bekräfta begäran skriftligt. Hen avböjer: det var ”bara en önskan”. Om något går fel finns inget som visar att de bad om det. Väntar ni ändå på grund av ett telefonsamtal?"]),
            pb(["Whose investigation?", "Vems utredning?"], ["{{person.legal.name}} asks what exactly an early notice would compromise: the investigation, or the provider's announcement? The authority is not the press. Why should your legal duty wait for their timing?", "{{person.legal.name}} frågar vad en tidig anmälan egentligen skulle äventyra: utredningen eller leverantörens kommunikation? Myndigheten är inte pressen. Varför ska er rättsliga skyldighet vänta på deras tidsplan?"])
          ] })
        ])
      }),

      pg("c7", ["A second wave", "En andra våg"], [
        "Day three. The provider's investigators have found more: the attacker also downloaded {{num.payslipMonths}} months of payslips.\n\nPayslips show far more than salary. They reveal sick pay, parental leave, wage garnishments and union fees, which is sensitive data about health, family and union membership.",
        "Dag tre. Leverantörens utredare har hittat mer: angriparen laddade också ned {{num.payslipMonths}} månader av lönebesked.\n\nLönebesked visar mycket mer än lön. De avslöjar sjuklön, föräldraledighet, löneutmätning och fackavgifter, alltså känsliga uppgifter om hälsa, familj och fackligt medlemskap."
      ], {
        variants: [
          vr("notified", [
            "Day three. Because you already notified, this is an update, not a first report. But the news is bad: the attacker also downloaded {{num.payslipMonths}} months of payslips.\n\nPayslips reveal sick pay, parental leave, wage garnishments and union fees, which is sensitive data about health, family and union membership.",
            "Dag tre. Eftersom ni redan har anmält är det här en komplettering, inte en första rapport. Men nyheten är dålig: angriparen laddade också ned {{num.payslipMonths}} månader av lönebesked.\n\nLönebesked avslöjar sjuklön, föräldraledighet, löneutmätning och fackavgifter, alltså känsliga uppgifter om hälsa, familj och fackligt medlemskap."
          ]),
          vr("waitedProvider", [
            "Day three. The provider still has not notified anyone, and your own deadline has passed while you waited. Now its investigators find that {{num.payslipMonths}} months of payslips were taken too.\n\nPayslips reveal sick pay, parental leave, wage garnishments and union fees: sensitive data about health, family and union membership.",
            "Dag tre. Leverantören har fortfarande inte anmält till någon, och er egen frist har gått ut medan ni väntade. Nu hittar dess utredare att även {{num.payslipMonths}} månader av lönebesked togs.\n\nLönebesked avslöjar sjuklön, föräldraledighet, löneutmätning och fackavgifter: känsliga uppgifter om hälsa, familj och fackligt medlemskap."
          ], ["Because you waited for the provider, you are now past your own 72 hours.", "Eftersom ni väntade på leverantören har ni nu passerat era egna 72 timmar."])
        ],
        choice: ask(["What do you do with the new facts?", "Vad gör ni med de nya uppgifterna?"], ["Updates staff and authorities the same day; sensitive data raises the stakes.", "Uppdaterar personal och myndigheter samma dag; känsliga uppgifter höjer insatsen."], [
          opt(["Update staff and the authority today", "Uppdatera personalen och myndigheten i dag"], "l4", ["Sick pay and union fees are sensitive data. Speed matters.", "Sjuklön och fackavgifter är känsliga uppgifter. Snabbhet spelar roll."], { pushback: [
            pb(["How do you word it?", "Hur formulerar ni det?"], ["Telling staff that sick pay, parental leave and garnishments were taken will frighten some more than the first breach did. Some will ask who else can now see their health details. How do you word an update about sensitive data without causing new harm?", "Att berätta att sjuklön, föräldraledighet och löneutmätning togs kommer att skrämma en del mer än det första intrånget. Några kommer att fråga vem mer som nu kan se deras hälsouppgifter. Hur formulerar ni en uppdatering om känsliga uppgifter utan att orsaka ny skada?"]),
            pb(["“Preliminary, don't quote us”", "”Preliminärt, citera oss inte”"], ["The provider says the payslip findings are preliminary and asks you not to cite them yet. If you update today and they revise, you correct yourselves in front of staff and the authority. Do you go with preliminary facts, or wait a day?", "Leverantören säger att uppgifterna om lönebesked är preliminära och ber er att inte citera dem ännu. Uppdaterar ni i dag och de reviderar, får ni rätta er inför personal och myndighet. Går ni ut med preliminära fakta, eller väntar ni en dag?"]),
            pb(["Who hears first?", "Vem får veta först?"], ["The union representative points out that union fees show who is a member, which some people never told colleagues. They want to brief members before an all-staff message goes out. Do you give the union a head start, or tell everyone at once?", "Den fackliga representanten påpekar att fackavgifterna visar vem som är medlem, något en del aldrig berättat för kollegor. Facket vill informera medlemmarna innan ett meddelande går till all personal. Ger ni facket ett försprång, eller berättar ni för alla samtidigt?"])
          ] }),
          opt(["Wait for the full forensic report", "Vänta på den fullständiga forensiska rapporten"], "l4", ["The report may take weeks.", "Rapporten kan ta veckor."], { pushback: [
            pb(["Weeks, not days", "Veckor, inte dagar"], ["The provider's investigators estimate the full report in several weeks. Until then, staff whose sick-pay and parental-leave records were taken know nothing. Can you justify weeks of silence about health data?", "Leverantörens utredare räknar med den fullständiga rapporten om flera veckor. Till dess vet de anställda vars uppgifter om sjuklön och föräldraledighet togs ingenting. Kan ni försvara veckor av tystnad om hälsouppgifter?"]),
            pb(["A journalist knows", "En journalist vet"], ["A journalist emails asking whether payslips were among the stolen data. They seem to know already. Do you confirm it to a reporter before you have told your own staff?", "En journalist mejlar och frågar om lönebesked fanns bland den stulna datan. Hen verkar redan veta. Bekräftar ni det för en reporter innan ni har berättat för er egen personal?"]),
            pb(["Without undue delay", "Utan onödigt dröjsmål"], ["{{person.dpo.name}} reminds you that new information must reach {{reg.dpaShort}} without undue delay, in stages if necessary. A pending report is no reason to hold back what you already know. What do you tell the authority, and when?", "{{person.dpo.name}} påminner om att nya uppgifter ska nå {{reg.dpaShort}} utan onödigt dröjsmål, i omgångar om det behövs. En kommande rapport är inget skäl att hålla inne med det ni redan vet. Vad säger ni till myndigheten, och när?"])
          ] }),
          opt(["Hand it to legal and say nothing yet", "Lämna det till juristen och säg inget ännu"], "l4", ["Legal advice is useful; silence is a decision too.", "Juridisk rådgivning är bra; tystnad är också ett beslut."], { pushback: [
            pb(["Legal says speak", "Juristen säger: tala"], ["{{person.legal.name}} replies within the hour: update the authority now and staff soon. Handing it to legal has produced the answer you hoped to avoid. Do you follow your own lawyer's advice, or look for a second opinion?", "{{person.legal.name}} svarar inom en timme: uppdatera myndigheten nu och personalen snart. Att lämna det till juristen gav just det svar ni ville undvika. Följer ni er egen jurists råd, eller söker ni en andra bedömning?"]),
            pb(["They read it elsewhere", "De läser det någon annanstans"], ["The provider sends an update to all its customers that mentions payslip data. Your staff see it before hearing anything from you. What do you say when they ask how long you knew?", "Leverantören skickar en uppdatering till alla sina kunder som nämner lönebesked. Er personal ser den innan de hört något från er. Vad svarar ni när de frågar hur länge ni har vetat?"]),
            pb(["Silence on the record", "Tystnad i protokollet"], ["Every day without a decision is now documented in legal's file. If the authority asks later, the record will show you knew and chose to wait. Who signs off on that silence?", "Varje dag utan beslut finns nu dokumenterad i juristens akt. Om myndigheten frågar senare visar akten att ni visste och valde att vänta. Vem tar på sig ansvaret för den tystnaden?"])
          ] })
        ])
      }),

      pg("l4", ["Stay or leave", "Stanna eller gå"], [
        "An extra board meeting. The directors ask {{person.cfo.name}} one question: should you leave {{supplier.vendor}}?\n\nMoving payroll to another provider normally takes six months of planning and testing. Staying means trusting a provider that lost your staff's data. Either answer will be quoted back to you later.",
        "Ett extra styrelsemöte. Ledamöterna ställer en fråga till {{person.cfo.name}}: ska ni lämna {{supplier.vendor}}?\n\nAtt flytta lönerna till en annan leverantör tar normalt sex månader av planering och tester. Att stanna innebär att lita på en leverantör som tappade bort personalens uppgifter. Båda svaren kommer att citeras för er senare."
      ], {
        long: true,
        skipTo: "c8",
        choice: ask(["What do you recommend?", "Vad rekommenderar ni?"], ["Separates the emotional answer from a planned, safe exit or remediation.", "Skiljer det känslomässiga svaret från en planerad, säker avveckling eller åtgärdsplan."], [
          opt(["Plan an exit, but stay until it is safe to move", "Planera för att lämna, men stanna tills det är säkert att flytta"], "c8", ["Sensible. Requires demanding evidence from the provider meanwhile.", "Förnuftigt. Kräver att ni begär underlag från leverantören under tiden."], { pushback: [
            pb(["“Give us a date”", "”Ge oss ett datum”"], ["A director says “planning an exit” sounds like doing nothing, and the press will ask why you still trust {{supplier.vendor}}. The board wants a date. Do you give a date you may not be able to keep?", "En ledamot säger att ”planera för att lämna” låter som att inte göra något, och att pressen kommer att fråga varför ni fortfarande litar på {{supplier.vendor}}. Styrelsen vill ha ett datum. Ger ni ett datum ni kanske inte kan hålla?"]),
            pb(["Evidence refused", "Underlag nekas"], ["You ask the provider for evidence of what has been fixed. It offers a two-page summary and declines to share its investigation report, citing confidentiality. How long do you stay with a provider that won't show you its work?", "Ni ber leverantören om belägg för vad som åtgärdats. Den erbjuder en sammanfattning på två sidor och vägrar dela utredningsrapporten med hänvisning till sekretess. Hur länge stannar ni hos en leverantör som inte visar vad den gjort?"]),
            pb(["Staff want out", "Personalen vill bort"], ["The union representative says members don't want their data in the same system for another six months. To them, staying is the company's choice, not a necessity. How do you explain why their data stays where it was stolen?", "Den fackliga representanten säger att medlemmarna inte vill ha sina uppgifter i samma system i sex månader till. För dem är det företagets val att stanna, inte en nödvändighet. Hur förklarar ni att deras uppgifter blir kvar där de stals?"])
          ] }),
          opt(["Terminate the contract now", "Säg upp avtalet nu"], "c8", ["Decisive. You have no other payroll system.", "Beslutsamt. Ni har inget annat lönesystem."], { set: "terminated", pushback: [
            pb(["Who runs next payroll?", "Vem kör nästa lön?"], ["{{person.cfo.name}} points out that the next payroll run is only weeks away and there is no other system. Terminating does not come with a replacement. Who calculates next month's salaries, and how?", "{{person.cfo.name}} påpekar att nästa lönekörning bara är några veckor bort och att det inte finns något annat system. En uppsägning kommer inte med en ersättare. Vem räknar ut nästa månads löner, och hur?"]),
            pb(["You may be in breach", "Ni kan bryta mot avtalet"], ["{{person.legal.name}} finds that the contract allows termination for cause only after a remediation period. Terminating now could make you the party in breach. Are you ready for a dispute with the company that holds all your payroll data?", "{{person.legal.name}} ser att avtalet bara tillåter uppsägning av särskilda skäl efter en period för åtgärder. Att säga upp nu kan göra er till den part som bryter avtalet. Är ni beredda på en tvist med företaget som har alla era lönedata?"]),
            pb(["Leaving mid-investigation", "Att gå mitt i utredningen"], ["Once terminated, the provider must return or delete your data, and you have no way to check either. Leaving angry could also mean less help with an investigation that isn't finished. What do you lose by walking out before it is done?", "Efter uppsägningen ska leverantören lämna tillbaka eller radera er data, och ni kan inte kontrollera någotdera. Att gå i vredesmod kan också ge mindre hjälp med en utredning som inte är klar. Vad förlorar ni på att gå innan den är färdig?"])
          ] })
        ])
      }),

      pg("c8", ["The next payroll run", "Nästa lönekörning"], [
        "Two weeks on, the provider says its platform has been rebuilt and cleaned. It wants to run next month's payroll as normal, on schedule.\n\nYour security team has only the provider's word for it: there is no independent report yet. The payroll run is in two weeks, and nobody wants a second missed payday.",
        "Två veckor senare säger leverantören att plattformen är ombyggd och rensad. Den vill köra nästa månads löner som vanligt, enligt schemat.\n\nErt säkerhetsteam har bara leverantörens ord på det: det finns ännu ingen oberoende rapport. Lönekörningen är om två veckor, och ingen vill missa en lönedag till."
      ], {
        variants: [vr("terminated", [
          "You have terminated the contract, and the provider has started handing back your data.\n\nThe next payroll run is in two weeks, and there is no system to run it in. A new provider needs months. Finance has a spreadsheet and a lot of goodwill, but no tested way to calculate tax and deductions for {{org.headcount|number}} people.",
          "Ni har sagt upp avtalet och leverantören har börjat lämna tillbaka er data.\n\nNästa lönekörning är om två veckor, och det finns inget system att köra den i. En ny leverantör behöver månader. Ekonomi har ett kalkylark och mycket god vilja, men inget testat sätt att räkna ut skatt och avdrag för {{org.headcount|number}} personer."
        ], ["Because the contract was terminated, every option now involves manual work.", "Eftersom avtalet sades upp innebär varje alternativ nu manuellt arbete."])],
        choice: ask(["How do you run next month's payroll?", "Hur kör ni nästa månads löner?"], ["Demands evidence of remediation and adds its own controls before trusting the service again.", "Kräver bevis på åtgärder och lägger till egna kontroller innan tjänsten får förtroende igen."], [
          opt(["Use the provider, with your own checks on every output", "Använd leverantören, med egna kontroller av varje resultat"], "c9", ["Trust but verify. Extra work for finance.", "Lita men kontrollera. Extra arbete för ekonomi."], { pushback: [
            pb(["What do the checks catch?", "Vad fångar kontrollerna?"], ["Finance can compare totals with last month, but cannot verify every tax calculation or bank account. A quiet change to a handful of accounts would pass. What exactly do your checks catch, and what don't they?", "Ekonomi kan jämföra totalsummor med förra månaden, men inte kontrollera varje skatteberäkning eller bankkonto. En tyst ändring av ett fåtal konton skulle slinka igenom. Vad fångar era kontroller egentligen, och vad missar de?"]),
            pb(["Finance is worn out", "Ekonomi är slutkörd"], ["The payroll team has worked overtime since payday and must now check every output by hand, every month. Two of them have asked for leave. How long can you keep this up, and who decides when the checks stop?", "Lönegruppen har jobbat övertid sedan lönedagen och ska nu granska varje resultat för hand, varje månad. Två av dem har bett om ledigt. Hur länge orkar ni hålla på, och vem bestämmer när kontrollerna upphör?"]),
            pb(["Checks delay the run", "Kontrollerna försenar körningen"], ["The provider says your extra checks will push its standard run past the window, and asks for sign-off on its normal schedule. Holding it longer risks another late payday. Do you shorten your checks to fit their timetable?", "Leverantören säger att era extra kontroller skjuter standardkörningen förbi tidsfönstret och vill ha ert godkännande enligt sitt vanliga schema. Att hålla kvar den längre riskerar en ny sen lönedag. Kortar ni kontrollerna för att passa deras tidsplan?"])
          ] }),
          opt(["Back to normal with the provider", "Tillbaka till det normala med leverantören"], "c9", ["Assumes the provider's word is enough.", "Förutsätter att leverantörens ord räcker."], { pushback: [
            pb(["Security won't sign", "Säkerhet skriver inte under"], ["{{person.ciso.name}} asks to record in writing that no independent report exists and that security did not approve the return to normal. If anything goes wrong, that note will be read aloud. Who signs the decision instead?", "{{person.ciso.name}} vill skriftligt notera att det inte finns någon oberoende rapport och att säkerhet inte godkänt återgången. Om något går fel kommer den anteckningen att läsas upp. Vem skriver under beslutet i stället?"]),
            pb(["“What has changed?”", "”Vad har ändrats?”"], ["An employee asks HR what is different about the system that lost their data. HR has nothing to say except that the provider says it is fixed. What do you tell staff asked to trust the same platform again?", "En anställd frågar HR vad som är annorlunda med systemet som tappade hens uppgifter. HR har inget att säga utom att leverantören säger att det är åtgärdat. Vad säger ni till personal som ska lita på samma plattform igen?"]),
            pb(["The board asked", "Styrelsen frågade"], ["The same directors who asked whether you should leave {{supplier.vendor}} will see payroll back to normal on the provider's word alone. One of them asks what evidence you were given. What do you show them?", "Samma ledamöter som frågade om ni borde lämna {{supplier.vendor}} ser nu lönerna tillbaka till det normala enbart på leverantörens ord. En av dem frågar vilka belägg ni fick. Vad visar ni?"])
          ] }),
          opt(["Manual payroll until the provider is independently cleared", "Manuell lönehantering tills leverantören granskats oberoende"], "c9", ["Safe and exhausting. Errors are likely.", "Säkert och utmattande. Fel är sannolika."], { pushback: [
            pb(["A spreadsheet for everyone", "Ett kalkylark för alla"], ["The first manual run calculates tax and deductions for {{org.headcount|number}} people in a spreadsheet. Errors are almost certain, and every one lands on someone's payslip. How many errors are acceptable, and who fixes them?", "Den första manuella körningen räknar ut skatt och avdrag för {{org.headcount|number}} personer i ett kalkylark. Fel är nästan säkra, och vart och ett hamnar på någons lönebesked. Hur många fel är acceptabla, och vem rättar dem?"]),
            pb(["Cleared by when?", "Granskad när?"], ["No independent review has been commissioned yet, and no firm can start for weeks. “Until cleared” could mean months of manual payroll. Do you set an end date, or accept an open-ended burden?", "Ingen oberoende granskning är beställd ännu, och ingen firma kan börja på flera veckor. ”Tills den granskats” kan betyda månader av manuell lönehantering. Sätter ni ett slutdatum, eller accepterar ni en börda utan slut?"]),
            pb(["Paying twice over", "Dubbla kostnader"], ["You keep paying the provider's fees for a service you aren't using, plus overtime for the manual work. {{person.cfo.name}} asks how long both costs can run. What would make you stop and go back?", "Ni fortsätter betala leverantörens avgifter för en tjänst ni inte använder, plus övertid för det manuella arbetet. {{person.cfo.name}} frågar hur länge båda kostnaderna kan löpa. Vad skulle få er att sluta och gå tillbaka?"])
          ] })
        ])
      }),

      pg("c9", ["What changes", "Vad som ändras"], [
        "A month later. Everyone was paid in the end, some of them late and some with the wrong amount.\n\nThe management team meets to decide what to do differently. Payroll was not the only critical service you buy from the cloud; the same thing could happen to your ERP, your email or your customer system tomorrow.",
        "En månad senare. Alla fick lön till slut, en del sent och en del med fel belopp.\n\nLedningsgruppen träffas för att bestämma vad ni ska göra annorlunda. Lönerna var inte den enda kritiska tjänst ni köper från molnet; samma sak kan hända ert affärssystem, er e-post eller ert kundsystem i morgon."
      ], {
        choice: ask(["What do you change first?", "Vad ändrar ni först?"], ["Builds a tested fallback for critical processes, not only better questionnaires.", "Bygger en testad reservlösning för kritiska processer, inte bara bättre enkäter."], [
          opt(["A tested manual fallback and exit plan for each critical SaaS", "En testad manuell reservlösning och avvecklingsplan för varje kritisk SaaS-tjänst"], "c10", ["Addresses the failure you actually had.", "Tar itu med det som faktiskt brast."], { pushback: [
            pb(["A year of work", "Ett års arbete"], ["IT counts the critical cloud services: more than a dozen, each owned by a different department. Building and testing a fallback for each will take a year. Which come first, and what stays uncovered meanwhile?", "IT räknar de kritiska molntjänsterna: fler än ett dussin, var och en ägd av en egen avdelning. Att bygga och testa en reservlösning för varje tar ett år. Vilka kommer först, och vad står oskyddat under tiden?"]),
            pb(["“Our system never fails”", "”Vårt system går aldrig ner”"], ["Department heads say they have no time to rehearse manual fallbacks for systems that “never fail”. Payroll's crisis was not theirs. Who makes them do it, and what happens if they don't?", "Avdelningschefer säger att de inte har tid att öva manuella reservlösningar för system som ”aldrig går ner”. Lönekrisen var inte deras. Vem får dem att göra det, och vad händer om de inte gör det?"]),
            pb(["Tested means real", "Testat betyder på riktigt"], ["A fallback that has never been tested is just a document. Testing payroll by hand means running a real month in parallel, with all the cost that brings. Are you prepared to pay for that, every year?", "En reservlösning som aldrig testats är bara ett dokument. Att testa lönerna för hand betyder att köra en riktig månad parallellt, med allt vad det kostar. Är ni beredda att betala för det, varje år?"])
          ] }),
          opt(["More security questions in procurement", "Fler säkerhetsfrågor vid upphandling"], "c10", ["Useful, and would not have paid anyone on time.", "Användbart, och hade inte fått ut några löner i tid."], { pushback: [
            pb(["They passed last time", "De klarade det förra gången"], ["{{person.supplierManager.name}} digs out the original procurement: {{supplier.vendor}} answered every security question well. More questions would not have stopped this breach. What would the new questions catch that the old ones missed?", "{{person.supplierManager.name}} letar fram den ursprungliga upphandlingen: {{supplier.vendor}} svarade bra på alla säkerhetsfrågor. Fler frågor hade inte stoppat intrånget. Vad skulle de nya frågorna fånga som de gamla missade?"]),
            pb(["Next payday?", "Nästa lönedag?"], ["{{person.cfo.name}} asks: if the same thing happens next payday, will the new questionnaire pay anyone? It won't. What do you tell staff who ask what has changed for them?", "{{person.cfo.name}} frågar: om samma sak händer nästa lönedag, får någon lön tack vare den nya enkäten? Nej. Vad säger ni till personal som frågar vad som har ändrats för dem?"]),
            pb(["Only for new contracts", "Bara för nya avtal"], ["The new questions apply only to future purchases. Every critical service you depend on today was bought under the old process. What do you do about those?", "De nya frågorna gäller bara framtida upphandlingar. Varje kritisk tjänst ni är beroende av i dag köptes enligt den gamla processen. Vad gör ni med dem?"])
          ] }),
          opt(["Rely on cyber insurance", "Förlita er på cyberförsäkringen"], "c10", ["Insurance pays later. Salaries are due tomorrow.", "Försäkringen betalar senare. Lönerna ska betalas i morgon."], { pushback: [
            pb(["The insurer asks first", "Försäkringsbolaget frågar först"], ["Before discussing any claim, the insurer asks for evidence of your own controls over third-party providers. You have little to show. Are you sure the policy covers a breach that happened at someone else's company?", "Innan något ärende diskuteras vill försäkringsbolaget se belägg för era egna kontroller av leverantörer. Ni har lite att visa. Är ni säkra på att försäkringen täcker ett intrång som skedde hos någon annan?"]),
            pb(["Insurance doesn't pay salaries", "Försäkringen betalar inga löner"], ["Insurance might reimburse costs months later, but it puts nothing in anyone's account on payday. Staff who went without pay did not need a reimbursement. What protects them next time?", "Försäkringen kan ersätta kostnader månader senare, men den sätter inga pengar på någons konto på lönedagen. Personal som blev utan lön behövde ingen ersättning i efterhand. Vad skyddar dem nästa gång?"]),
            pb(["A condition at renewal", "Ett villkor vid förnyelsen"], ["At renewal the insurer raises the premium and makes a tested fallback for critical services a condition of cover. You are back where you started, now with a deadline. Who builds it?", "Vid förnyelsen höjer försäkringsbolaget premien och gör en testad reservlösning för kritiska tjänster till ett villkor. Ni är tillbaka där ni började, nu med en tidsgräns. Vem bygger den?"])
          ] })
        ])
      }),

      pg("c10", ["The staff survey", "Medarbetarenkäten"], [
        "The annual staff survey comes back. Among the usual comments, one new free-text answer keeps returning in different words: “Can I trust the company with my data?”\n\nHR wants to answer it in the next all-staff meeting. How you answer will show whether anything has really changed.",
        "Den årliga medarbetarenkäten kommer tillbaka. Bland de vanliga kommentarerna återkommer ett nytt fritextsvar med olika ord: ”Kan jag lita på företaget med mina uppgifter?”\n\nHR vill svara på det på nästa personalmöte. Hur ni svarar kommer att visa om något verkligen har förändrats."
      ], {
        choice: ask(["How do you answer that question?", "Hur besvarar ni den frågan?"], ["Answers with concrete changes and owners, not reassurance.", "Svarar med konkreta förändringar och ansvariga, inte med lugnande ord."], [
          opt(["Publish what changed and who owns it", "Publicera vad som ändrats och vem som äger det"], "r-end", ["Specific and checkable.", "Konkret och möjligt att följa upp."], { pushback: [
            pb(["Mostly plans", "Mest planer"], ["When HR drafts the list, several items are still plans rather than changes. Publishing them invites the question “why isn't this done?”. Do you publish the plans as they are, or wait until they are finished?", "När HR skriver listan är flera punkter fortfarande planer snarare än förändringar. Att publicera dem bjuder in frågan ”varför är det här inte klart?”. Publicerar ni planerna som de är, eller väntar ni tills de är genomförda?"]),
            pb(["Owners don't want names", "Ägarna vill inte nämnas"], ["Two managers ask not to be named publicly as owners, worried they will be blamed for the next incident. Without names, the list is just promises. Do you name them anyway?", "Två chefer ber att inte nämnas offentligt som ansvariga, oroliga för att få skulden vid nästa incident. Utan namn är listan bara löften. Namnger ni dem ändå?"]),
            pb(["The union keeps score", "Facket för protokoll"], ["The union says it will check every item at next year's survey and publish its own scorecard. Your list becomes a commitment you will be measured against. Are you ready to be held to every line?", "Facket säger att det tänker följa upp varje punkt vid nästa års enkät och publicera en egen bedömning. Er lista blir ett åtagande ni mäts mot. Är ni beredda att stå till svars för varje rad?"])
          ] }),
          opt(["A message from the CEO about values", "Ett meddelande från vd om värderingar"], "r-end", ["Warm words without evidence.", "Varma ord utan belägg."], { pushback: [
            pb(["“So what changed?”", "”Så vad har ändrats?”"], ["The survey asked whether staff can trust the company with their data. A message about values doesn't answer that. What will {{person.ceo.name}} say when someone at the all-staff meeting asks “so what changed?”", "Enkäten frågade om personalen kan lita på företaget med sina uppgifter. Ett meddelande om värderingar svarar inte på det. Vad säger {{person.ceo.name}} när någon på personalmötet frågar ”så vad har ändrats?”"]),
            pb(["Read as spin", "Läses som spinn"], ["{{person.comms.name}} warns that a values message after a breach is often read as spin, and staff will hold it up against what happened on payday. Do you still send it as it is, or add something concrete?", "{{person.comms.name}} varnar för att ett värderingsbudskap efter ett intrång ofta läses som spinn, och att personalen kommer att jämföra det med vad som hände på lönedagen. Skickar ni det ändå som det är, eller lägger ni till något konkret?"]),
            pb(["HR left to answer", "HR får svara"], ["{{person.hr.name}} will face the follow-up questions after the CEO's message, with no concrete changes to point to. HR asks for specifics or a different approach. Do you give them facts, or ask them to repeat the message?", "{{person.hr.name}} får ta följdfrågorna efter vd:s meddelande, utan några konkreta förändringar att peka på. HR ber om detaljer eller ett annat grepp. Ger ni dem fakta, eller ber ni dem upprepa budskapet?"])
          ] })
        ])
      }),

      pg("r-end", ["Outcome", "Utfall"], ["Routing to the ending.", "Vidare till slutet."], {
        route: rt([
          [["notified", "staffTold", "paidManual"], "e1"],
          ["notified", "e2"],
          ["paidManual", "e3"],
          [null, "e4"]
        ])
      }),

      pg("e1", ["A month later", "En månad senare"], ["Payday went almost unnoticed. Your own fallback paid everyone on time, staff heard about the breach from you before they read it anywhere else, and the authority had your notification within 72 hours.\n\nWhen the provider's breach reaches the news, your company is mentioned only as a customer that handled it well.", "Lönedagen gick nästan obemärkt förbi. Er egen reservlösning betalade alla i tid, personalen fick höra om intrånget från er innan de läste om det någon annanstans och myndigheten hade er anmälan inom 72 timmar.\n\nNär leverantörens intrång når nyheterna nämns ert företag bara som en kund som hanterade det väl."], {
        ending: end(1, ["Paid, told and notified", "Betalt, informerat och anmält"], [
          "Everyone was paid on time from your own fallback, staff heard it from you first, and the authority got your notification within 72 hours. The provider's breach stayed the provider's crisis.",
          "Alla fick lön i tid från er egen reservlösning, personalen hörde det från er först och myndigheten fick er anmälan inom 72 timmar. Leverantörens intrång förblev leverantörens kris."
        ])
      }),
      pg("e2", ["A month later", "En månad senare"], ["The authority received your notification in time, and the paperwork is in order. But people noticed what went wrong for them: late salaries, or information that came after the rumours.\n\nIn the corridors, HR is “the department that didn't tell us”. Rebuilding that trust will take far longer than the breach did.", "Myndigheten fick er anmälan i tid och pappersarbetet är i ordning. Men folk märkte det som gick fel för dem: sena löner, eller information som kom efter ryktena.\n\nI korridorerna är HR ”avdelningen som inte berättade”. Att bygga upp det förtroendet igen tar mycket längre tid än intrånget gjorde."], {
        ending: end(2, ["Compliant, but people noticed", "Regelrätt, men folk märkte det"], [
          "The notification was on time, but late salaries or late information left staff angry. Trust in HR takes a year to rebuild.",
          "Anmälan kom i tid, men försenade löner eller sen information gjorde personalen arg. Förtroendet för HR tar ett år att bygga upp igen."
        ])
      }),
      pg("e3", ["Two months later", "Två månader senare"], ["Salaries went out, but you waited for the provider to act and missed your own notification deadline.\n\nThe authority's letter is blunt: as the controller, the breach was your responsibility from the first morning, and waiting for a processor is no excuse. The criticism is published on the authority's website.", "Lönerna betalades ut, men ni väntade på att leverantören skulle agera och missade er egen tidsfrist för anmälan.\n\nMyndighetens brev är rakt: som personuppgiftsansvariga var intrånget ert ansvar från första morgonen, och att vänta på ett biträde är ingen ursäkt. Kritiken publiceras på myndighetens webbplats."], {
        ending: end(3, ["Paid, but out of time", "Betalt, men för sent anmält"], [
          "Salaries went out, but you waited for the provider and missed your own deadline. The authority criticises you for treating the breach as someone else's problem.",
          "Lönerna betalades ut, men ni väntade på leverantören och missade er egen tidsfrist. Myndigheten kritiserar er för att ha behandlat intrånget som någon annans problem."
        ])
      }),
      pg("e4", ["Two months later", "Två månader senare"], ["Salaries were late, the notification later still, and the fraudsters reached your staff before you did. Several employees lost money to fake portals.\n\nThe union has filed a formal complaint, the authority has opened a case, and the story of the company that left its staff unpaid and uninformed is still circulating.", "Lönerna blev sena, anmälan ännu senare och bedragarna nådde personalen före er. Flera anställda förlorade pengar på falska portaler.\n\nFacket har lämnat in ett formellt klagomål, myndigheten har öppnat ett ärende och historien om företaget som lämnade sin personal utan lön och utan information cirkulerar fortfarande."], {
        ending: end(4, ["Unpaid and uninformed", "Utan lön och utan besked"], [
          "Salaries were late, notification later still, and fraudsters reached staff before you did. The union files a complaint and the authority opens a case.",
          "Lönerna blev sena, anmälan ännu senare och bedragarna nådde personalen före er. Facket lämnar in ett klagomål och myndigheten öppnar ett ärende."
        ])
      }),

      // Break-away: public blame.
      pg("x1", ["Public blame", "Offentlig skuld"], [
        "Your post naming {{supplier.vendor}} is shared widely and picked up by a trade site.\n\nWithin an hour the provider replies publicly: its investigation shows that the access to your data used valid credentials issued to your own company. Suddenly the question in the comments is not what the provider did, but what you did.",
        "Ert inlägg som pekar ut {{supplier.vendor}} sprids snabbt och plockas upp av en branschsajt.\n\nInom en timme svarar leverantören offentligt: dess utredning visar att åtkomsten till er data skedde med giltiga inloggningsuppgifter utfärdade till ert eget företag. Plötsligt handlar frågan i kommentarerna inte om vad leverantören gjorde, utan om vad ni gjorde."
      ], {
        injects: [
          inj("b2-4", 420, "socialPost", "socialMedia", "high", "disputed", [
            "{{supplier.vendor}}: “Our investigation shows the access to this customer's data used valid credentials issued to the customer. We are cooperating fully.”",
            "{{supplier.vendor}}: ”Vår utredning visar att åtkomsten till den här kundens data skedde med giltiga inloggningsuppgifter som kunden själv fått. Vi samarbetar fullt ut.”"
          ], { facilitatorNote: ["Disputed: it may be true for one account, and it changes the story completely.", "Omstritt: det kan stämma för ett konto, och det förändrar berättelsen helt."], tests: ["lo2"] })
        ],
        choice: ask(["How do you respond?", "Hur svarar ni?"], ["Stops the public argument and checks the claim internally.", "Avbryter den offentliga diskussionen och kontrollerar påståendet internt."], [
          opt(["Stand by the post", "Stå fast vid inlägget"], "x2", ["Now it is a public dispute you may lose.", "Nu är det en offentlig tvist ni kan förlora."], { pushback: [
            pb(["Unchecked claim", "Okontrollerat påstående"], ["{{person.ciso.name}} has not yet checked whether any of your own accounts were used. Standing by the post means defending your claim against one you have not disproved. What do you do if theirs turns out to be true?", "{{person.ciso.name}} har ännu inte kontrollerat om något av era egna konton användes. Att stå fast vid inlägget är att försvara ert påstående mot ett ni inte har motbevisat. Vad gör ni om deras visar sig stämma?"]),
            pb(["“Where is your evidence?”", "”Var är era belägg?”"], ["{{person.comms.name}} says journalists are asking for your evidence, and the only answer so far is “we believe it”. Every hour the post stays up, the story is the dispute, not your staff. Who is going to front this?", "{{person.comms.name}} säger att journalister ber om era belägg, och det enda svaret hittills är ”vi tror det”. Varje timme inlägget ligger kvar handlar nyheten om bråket, inte om er personal. Vem ska stå för det här utåt?"]),
            pb(["“Look after us first”", "”Ta hand om oss först”"], ["Staff still waiting for answers about their own data and pay are reading the argument in the comments. One writes: “Look after us first.” How do you justify a public fight to the people still waiting on you?", "Anställda som fortfarande väntar på besked om sina uppgifter och sin lön läser bråket i kommentarerna. En skriver: ”Ta hand om oss först.” Hur försvarar ni ett offentligt bråk inför dem som fortfarande väntar på er?"])
          ] }),
          opt(["Take it down and check the claim", "Ta bort inlägget och kontrollera påståendet"], "x2", ["Late but wise.", "Sent men klokt."], { pushback: [
            pb(["Deleted, not gone", "Raderat, inte borta"], ["The deletion is noticed within minutes, and screenshots are already circulating with the comment “they knew”. Removing the post does not remove it. Do you publish an explanation, or stay silent?", "Raderingen märks inom några minuter, och skärmbilder cirkulerar redan med kommentaren ”de visste”. Att ta bort inlägget tar inte bort det. Publicerar ni en förklaring, eller håller ni tyst?"]),
            pb(["Checking takes days", "Kontrollen tar dagar"], ["{{person.ciso.name}} says checking every account with access to the provider will take days, not hours. Meanwhile the provider's claim stands unanswered in public. What do you say while you check?", "{{person.ciso.name}} säger att det tar dagar, inte timmar, att gå igenom alla konton med åtkomst till leverantören. Under tiden står leverantörens påstående obesvarat offentligt. Vad säger ni medan ni kontrollerar?"]),
            pb(["They want an apology", "De vill ha en ursäkt"], ["The provider asks for a public apology as well as the deletion. An apology would concede a point you have not yet checked. Do you apologise to end it, or hold out until you know?", "Leverantören kräver en offentlig ursäkt utöver raderingen. En ursäkt vore att medge något ni ännu inte kontrollerat. Ber ni om ursäkt för att avsluta det, eller håller ni emot tills ni vet?"])
          ] })
        ])
      }),
      pg("x2", ["Fraudsters move in", "Bedragarna hakar på"], [
        "The public dispute has made your staff an easy target. Fake “compensation” sites appear overnight, promising payouts to affected employees of {{org.name}}.\n\nTo claim, visitors must log in with their bank ID. By morning, several employees have done so, and one reports money missing from their account.",
        "Det offentliga bråket har gjort er personal till ett lätt mål. Falska ”ersättningssidor” dyker upp under natten och lovar utbetalningar till drabbade anställda på {{org.name}}.\n\nFör att få ersättning måste besökarna logga in med bank-id. På morgonen har flera anställda gjort det, och en rapporterar att pengar saknas på kontot."
      ], {
        choice: ask(["What do you do?", "Vad gör ni?"], ["Warns staff directly and reports the sites.", "Varnar personalen direkt och anmäler sidorna."], [
          opt(["Warn staff and the public", "Varna personalen och allmänheten"], "x3", ["Necessary, and it keeps the story alive.", "Nödvändigt, och det håller liv i historien."], { pushback: [
            pb(["Back in the headlines", "Tillbaka i rubrikerna"], ["A public warning puts {{org.name}} in tomorrow's news again, next to the word “fraud”. {{person.comms.name}} wants to wait a day. Do you accept the coverage to reach people faster?", "En offentlig varning sätter {{org.name}} i morgondagens nyheter igen, bredvid ordet ”bedrägeri”. {{person.comms.name}} vill vänta en dag. Accepterar ni rubrikerna för att nå folk snabbare?"]),
            pb(["What is genuine?", "Vad är äkta?"], ["Your warning lists the fake sites, and new ones appear with slightly different names. Some readers now suspect your real HR portal too. How do you tell people what is genuine?", "Er varning listar de falska sidorna, och nya dyker upp med lite andra namn. En del läsare misstänker nu även er riktiga HR-portal. Hur talar ni om för folk vad som är äkta?"]),
            pb(["Who covers the loss?", "Vem står för förlusten?"], ["The employee who lost money asks whether the company will cover it, since the fake site used your name. A public warning does not answer that. Do you reimburse them, and then everyone else who comes forward?", "Den anställda som förlorade pengar frågar om företaget ersätter det, eftersom den falska sidan använde ert namn. En offentlig varning svarar inte på det. Ersätter ni hen, och sedan alla andra som hör av sig?"])
          ] }),
          opt(["Warn staff only", "Varna bara personalen"], "x3", ["Narrower, quieter.", "Smalare, tystare."], { pushback: [
            pb(["Outside your channels", "Utanför era kanaler"], ["The fake sites also target former employees and staff's families, who are not on your internal channels. Warning only current staff leaves them exposed. Who protects the people you cannot reach internally?", "De falska sidorna riktar sig också till tidigare anställda och personalens familjer, som inte finns i era interna kanaler. Att bara varna nuvarande personal lämnar dem oskyddade. Vem skyddar dem ni inte når internt?"]),
            pb(["Quiet looks like hiding", "Tystnad ser ut som mörkläggning"], ["A journalist asks why you warned staff internally but said nothing publicly while fraud sites used your name. Quiet now looks like concealment. What is your answer?", "En journalist frågar varför ni varnade personalen internt men inte sa något offentligt medan bedrägerisidor använde ert namn. Tystnaden ser nu ut som mörkläggning. Vad svarar ni?"]),
            pb(["The warning leaks", "Varningen läcker"], ["Within an hour your internal warning is posted online, out of context. Now it looks as if you kept something from the public. Do you publish it yourselves, late, or let the leaked version stand?", "Inom en timme har er interna varning lagts ut på nätet, lösryckt. Nu ser det ut som att ni höll något undan allmänheten. Publicerar ni den själva, sent, eller låter ni den läckta versionen stå?"])
          ] })
        ])
      }),
      pg("x3", ["Unpaid", "Utan lön"], [
        "Salaries are still unpaid while you and the provider argue in public, and the dispute is now in the national news.\n\nThe union calls a meeting for all staff tomorrow morning and asks management to attend and explain. People want to know when they will be paid, not who is to blame.",
        "Lönerna är fortfarande obetalda medan ni och leverantören grälar offentligt, och tvisten finns nu i riksnyheterna.\n\nFacket kallar till ett möte för all personal i morgon bitti och ber ledningen att komma och förklara. Folk vill veta när de får lön, inte vem som bär skulden."
      ], {
        choice: ask(["What do you offer staff?", "Vad erbjuder ni personalen?"], ["Puts people's livelihoods first with an immediate advance.", "Sätter människors försörjning först med ett omedelbart förskott."], [
          opt(["Emergency salary advances today", "Akuta löneförskott i dag"], "x4", ["Expensive and right.", "Dyrt och rätt."], { pushback: [
            pb(["Paid how?", "Betalt hur?"], ["Finance asks how to pay advances today without the payroll system: amounts, accounts and tax all by hand. Mistakes are certain. Do you pay a flat sum to everyone, or only to those who ask?", "Ekonomi frågar hur förskott ska betalas i dag utan lönesystemet: belopp, konton och skatt, allt för hand. Fel är oundvikliga. Betalar ni ett fast belopp till alla, eller bara till dem som ber om det?"]),
            pb(["Who has to ask?", "Vem måste be?"], ["Paying everyone is a large sum today; paying only those who ask forces staff to admit they are struggling. HR worries about fairness and dignity. Where do you draw the line?", "Att betala alla är en stor summa i dag; att bara betala dem som ber om det tvingar anställda att erkänna att de har det svårt. HR oroar sig för rättvisa och värdighet. Var drar ni gränsen?"]),
            pb(["An admission?", "Ett medgivande?"], ["{{person.legal.name}} warns that advances announced at the union meeting may be read as admitting fault, in the middle of a public dispute with the provider. Do you still announce them tomorrow morning?", "{{person.legal.name}} varnar för att förskott som utlovas på fackets möte kan tolkas som ett medgivande av skuld, mitt i en offentlig tvist med leverantören. Utlovar ni dem ändå i morgon bitti?"])
          ] }),
          opt(["Ask for patience", "Be om tålamod"], "x4", ["Patience ran out a week ago.", "Tålamodet tog slut för en vecka sedan."], { pushback: [
            pb(["Patience for what?", "Tålamod med vad?"], ["Tomorrow you stand in front of all staff and ask for patience, with no date for payment. The union representative asks what exactly people are being asked to wait for. What date can you give?", "I morgon står ni inför all personal och ber om tålamod, utan något datum för lönen. Den fackliga representanten frågar vad folk egentligen ska vänta på. Vilket datum kan ni ge?"]),
            pb(["The bills arrive", "Räkningarna kommer"], ["Staff send overdraft notices and late-payment letters to HR as evidence, and want the company to cover them. Do you keep asking for patience while the costs land on them?", "Anställda skickar övertrasseringsbesked och påminnelser till HR som bevis, och vill att företaget står för kostnaderna. Fortsätter ni be om tålamod medan kostnaderna hamnar hos dem?"]),
            pb(["Quoted nationally", "Citerat i riksmedia"], ["A journalist asks to attend the union meeting. Asking unpaid staff for patience will be quoted in the national news. Is that the line you want in tomorrow's headlines?", "En journalist ber att få vara med på fackets möte. Att be personal utan lön om tålamod kommer att citeras i riksnyheterna. Är det den meningen ni vill se i morgondagens rubriker?"])
          ] })
        ])
      }),
      pg("x4", ["The letter", "Brevet"], [
        "A registered letter from {{supplier.vendor}}'s lawyers: retract your public statements within five working days, or face a claim for damages to their reputation.\n\nYour own lawyers say the provider's claim about your credentials may well be true. The fight has become more expensive than the breach.",
        "Ett rekommenderat brev från {{supplier.vendor}}s jurister: ta tillbaka era offentliga uttalanden inom fem arbetsdagar, annars väntar ett skadeståndskrav för skadat anseende.\n\nEra egna jurister säger att leverantörens påstående om era inloggningsuppgifter mycket väl kan stämma. Bråket har blivit dyrare än intrånget."
      ], {
        choice: ask(["How do you answer?", "Hur svarar ni?"], ["Takes legal advice before saying anything else in public.", "Tar juridisk rådgivning innan något mer sägs offentligt."], [
          opt(["Retract and settle quietly", "Ta tillbaka och förlik er i tysthet"], "e5", ["Ends the dispute, not the damage.", "Avslutar tvisten, inte skadan."], { pushback: [
            pb(["Staff read the retraction", "Personalen läser rättelsen"], ["Your retraction will be public. Staff who heard management blame the provider now read that you take it back. How do you explain the reversal to them?", "Er rättelse blir offentlig. Personal som hörde ledningen skylla på leverantören läser nu att ni tar tillbaka det. Hur förklarar ni omsvängningen för dem?"]),
            pb(["A gagging clause", "En tystnadsklausul"], ["The provider's lawyers want a confidentiality clause in the settlement. It could limit what you can tell staff and the authority later. Do you accept silence as the price of ending the dispute?", "Leverantörens jurister vill ha en sekretessklausul i förlikningen. Den kan begränsa vad ni senare kan säga till personalen och myndigheten. Accepterar ni tystnad som priset för att avsluta tvisten?"]),
            pb(["Who owns the post?", "Vem äger inlägget?"], ["The board asks who authorised the original post, now that it is being retracted. Someone will be named. Who takes responsibility, and what does that mean for them?", "Styrelsen frågar vem som godkände det ursprungliga inlägget, nu när det tas tillbaka. Någon kommer att pekas ut. Vem tar ansvaret, och vad innebär det för den personen?"])
          ] }),
          opt(["Fight it", "Ta striden"], "e5", ["Months of legal costs during a crisis.", "Månader av rättegångskostnader mitt i en kris."], { pushback: [
            pb(["Your lawyers doubt it", "Era jurister tvivlar"], ["Your own lawyers have said the provider's claim about your credentials may well be true. Fighting means arguing in court a point you may lose. What is your case actually built on?", "Era egna jurister har sagt att leverantörens påstående om era inloggningsuppgifter mycket väl kan stämma. Att ta striden är att i domstol driva en sak ni kan förlora. Vad bygger ert fall egentligen på?"]),
            pb(["Money and attention", "Pengar och uppmärksamhet"], ["{{person.cfo.name}} estimates months of legal costs while staff are still owed salary and the payroll problem is unsolved. The same people would run both. Where do you spend money and attention first?", "{{person.cfo.name}} räknar med månader av rättegångskostnader medan personalen fortfarande har lön att få och löneproblemet är olöst. Samma personer skulle sköta båda. Var lägger ni pengar och uppmärksamhet först?"]),
            pb(["Your own logs in court", "Era egna loggar i rätten"], ["In a lawsuit both sides must produce evidence, including your access logs and internal messages about the post. Are you ready for those to be read out in court?", "I en rättegång måste båda parter lägga fram bevis, även era åtkomstloggar och interna meddelanden om inlägget. Är ni beredda på att de läses upp i rätten?"])
          ] })
        ])
      }),
      pg("e5", ["Three months later", "Tre månader senare"], ["The public fight with your own provider became the story and buried everything that mattered. Staff went unpaid for days, fraudsters emptied accounts, and nobody remembered to notify the authority.\n\nThe provider's claim for damages is still in court, and so is the authority's case against you.", "Det offentliga bråket med er egen leverantör blev historien och begravde allt som var viktigt. Personalen blev utan lön i flera dagar, bedragare tömde konton och ingen kom ihåg att anmäla till myndigheten.\n\nLeverantörens skadeståndskrav ligger fortfarande i domstol, och det gör även myndighetens ärende mot er."], {
        ending: end(5, ["The fight became the story", "Bråket blev nyheten"], [
          "A public fight with your own provider buried the real issues: staff went unpaid, fraudsters had a field day and the notification was forgotten.",
          "Ett offentligt bråk med er egen leverantör begravde de verkliga frågorna: personalen blev utan lön, bedragarna fick fritt spelrum och anmälan glömdes bort."
        ])
      })
    ],

    debrief: {
      keyLessons: [
        L(["A SaaS outage on a critical day needs your own fallback, prepared before it is needed.", "Ett avbrott i en SaaS-tjänst en kritisk dag kräver en egen reservlösning, förberedd innan den behövs."]),
        L(["The controller's duty to notify does not move to the processor.", "Den personuppgiftsansvariges skyldighet att anmäla flyttar inte till biträdet."]),
        L(["Staff whose own data is affected need to hear it from you first.", "Personal vars egna uppgifter berörs behöver höra det från er först."]),
        L(["Fraudsters exploit incidents within hours: freeze changes to payment details.", "Bedragare utnyttjar incidenter inom några timmar: frys ändringar av betalningsuppgifter."])
      ],
      strengthsToLookFor: [
        L(["Starting a manual payroll fallback before the provider's update", "Att börja på en manuell reservlösning före leverantörens uppdatering"]),
        L(["Notifying as controller within 72 hours", "Att anmäla som personuppgiftsansvarig inom 72 timmar"]),
        L(["Freezing bank-detail changes", "Att frysa ändringar av bankuppgifter"])
      ],
      commonGaps: [
        L(["Waiting for the provider to solve it", "Att vänta på att leverantören ska lösa det"]),
        L(["Assuming the provider's notification covers you", "Att anta att leverantörens anmälan täcker er"]),
        L(["Arguing with the provider in public", "Att bråka med leverantören offentligt"])
      ],
      suggestedActions: [
        act(["Write and test a manual payroll fallback.", "Skriv och testa en manuell reservrutin för löner."], "cfo", "high"),
        act(["Map controller and processor duties for each critical SaaS provider.", "Kartlägg ansvaret som personuppgiftsansvarig och biträde för varje kritisk SaaS-leverantör."], "dpo", "high"),
        act(["Require phone verification of all bank-detail changes.", "Kräv telefonverifiering av alla ändringar av bankuppgifter."], "hr", "medium")
      ]
    }
  });
})();
